import { mkdirSync, writeFileSync, existsSync, rmSync } from "node:fs";
import { dirname } from "node:path";

if (!existsSync("package.json") || !existsSync("src/lib/me/badges.ts")) {
  console.error("Run this inside the Men-s-Social-True folder, after Step 12 (Me tab).");
  process.exit(1);
}
for (const path of [".next", "setup-step-12.mjs"]) {
  if (existsSync(path)) { rmSync(path, { recursive: true, force: true }); console.log("  removed", path); }
}

const files = {
  "src/app/(app)/account/new-password/page.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport { useRouter } from \"next/navigation\";\nimport { Loader2 } from \"lucide-react\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { account, useAccount } from \"@/lib/account/useAccount\";\n\n/** He arrives here from the \"reset your password\" email link. */\nexport default function NewPasswordPage() {\n  const acc = useAccount();\n  const router = useRouter();\n  const showToast = useToast();\n  const [password, setPassword] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  async function submit(e: React.FormEvent) {\n    e.preventDefault();\n    setBusy(true);\n    const r = await account.setNewPassword(password);\n    setBusy(false);\n    if (r.error) return setError(r.error);\n    showToast(\"New password saved\");\n    router.push(\"/me\");\n  }\n\n  return (\n    <div className=\"space-y-5\">\n      <h1 className=\"text-2xl font-bold\">Choose a new password</h1>\n      {acc.status === \"loading\" ? (\n        <Loader2 className=\"mx-auto animate-spin text-ink-soft\" />\n      ) : acc.status !== \"signedIn\" ? (\n        <p className=\"rounded-3xl bg-surface p-5 text-sm text-ink-soft ring-1 ring-line\">\n          This link has expired. Go to Me → Log in → &ldquo;Forgot password?&rdquo; to get a new one.\n        </p>\n      ) : (\n        <form onSubmit={submit} className=\"space-y-3\">\n          <input\n            type=\"password\"\n            autoComplete=\"new-password\"\n            minLength={8}\n            required\n            placeholder=\"At least 8 characters\"\n            value={password}\n            onChange={(e) => setPassword(e.target.value)}\n            className=\"w-full rounded-2xl bg-surface px-4 py-3 text-sm outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\"\n          />\n          {error && <p role=\"alert\" className=\"text-sm text-red-700\">{error}</p>}\n          <button disabled={busy} className=\"w-full rounded-full bg-forest py-3.5 text-sm font-semibold text-white disabled:opacity-60\">\n            Save password\n          </button>\n        </form>\n      )}\n    </div>\n  );\n}\n",
  "src/app/(app)/account/page.tsx": "\"use client\";\n\nimport { Suspense, useState } from \"react\";\nimport Link from \"next/link\";\nimport { useRouter, useSearchParams } from \"next/navigation\";\nimport { ArrowLeft, Eye, EyeOff, Loader2, Lock, Mail, Smartphone } from \"lucide-react\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { account, AUTH_METHODS, useAccount } from \"@/lib/account/useAccount\";\n\ntype Mode = \"signup\" | \"login\" | \"reset\";\n\nexport default function AccountPage() {\n  return (\n    <Suspense>\n      <AccountInner />\n    </Suspense>\n  );\n}\n\nfunction AccountInner() {\n  const router = useRouter();\n  const params = useSearchParams();\n  const showToast = useToast();\n  const acc = useAccount();\n  const [mode, setMode] = useState<Mode>(params.get(\"mode\") === \"login\" ? \"login\" : \"signup\");\n  const [phoneOpen, setPhoneOpen] = useState(false);\n\n  // Where to go after signing in: ?next=/man from the welcome screen, otherwise Me\n  const next = params.get(\"next\");\n  const afterSignIn = next && next.startsWith(\"/\") && !next.startsWith(\"//\") ? next : \"/me\";\n  const done = (msg: string) => {\n    showToast(msg);\n    router.push(afterSignIn);\n  };\n\n  if (acc.status === \"signedIn\") {\n    return (\n      <Shell>\n        <div className=\"rounded-3xl bg-surface p-6 text-center ring-1 ring-line\">\n          <p className=\"font-semibold\">You&apos;re signed in</p>\n          <Link href={afterSignIn} className=\"mt-4 inline-block rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n            Continue\n          </Link>\n        </div>\n      </Shell>\n    );\n  }\n  if (acc.status === \"unavailable\") {\n    return (\n      <Shell>\n        <p className=\"rounded-3xl bg-surface p-6 text-sm text-ink-soft ring-1 ring-line\">Accounts aren&apos;t switched on yet. You can keep using the app as a guest.</p>\n      </Shell>\n    );\n  }\n\n  return (\n    <Shell>\n      <div>\n        <h1 className=\"text-2xl font-bold\">{mode === \"login\" ? \"Welcome back\" : mode === \"reset\" ? \"Reset your password\" : \"Create your free account\"}</h1>\n        <p className=\"mt-1 text-sm text-ink-soft\">\n          {mode === \"reset\"\n            ? \"We'll email you a link to choose a new password.\"\n            : \"Keep your points, badges and progress safe, even if you change phones. Only you can see your data.\"}\n        </p>\n      </div>\n\n      {mode !== \"reset\" && (\n        <div className=\"inline-flex w-full rounded-full bg-surface p-1 text-sm font-semibold ring-1 ring-line\" role=\"tablist\">\n          {([\"signup\", \"login\"] as const).map((m) => (\n            <button key={m} role=\"tab\" aria-selected={mode === m} onClick={() => setMode(m)} className={`flex-1 rounded-full py-2 ${mode === m ? \"bg-forest-deep text-white\" : \"text-ink-soft\"}`}>\n              {m === \"signup\" ? \"Sign up\" : \"Log in\"}\n            </button>\n          ))}\n        </div>\n      )}\n\n      {mode !== \"reset\" && (\n        <div className=\"space-y-2\">\n          <button\n            onClick={async () => {\n              const r = await account.signInGoogle();\n              if (r.error) showToast(r.error);\n            }}\n            disabled={!AUTH_METHODS.google}\n            className=\"flex w-full items-center justify-center gap-3 rounded-full bg-surface py-3.5 text-sm font-semibold ring-1 ring-line disabled:opacity-50\"\n          >\n            <GoogleMark /> Continue with Google\n            {!AUTH_METHODS.google && <span className=\"rounded-full bg-bg px-2 py-0.5 text-[10px] text-ink-soft ring-1 ring-line\">Soon</span>}\n          </button>\n          <button\n            onClick={() => setPhoneOpen((o) => !o)}\n            disabled={!AUTH_METHODS.phone}\n            aria-expanded={phoneOpen}\n            className=\"flex w-full items-center justify-center gap-3 rounded-full bg-surface py-3.5 text-sm font-semibold ring-1 ring-line disabled:opacity-50\"\n          >\n            <Smartphone size={18} className=\"text-forest\" /> Continue with phone number\n            {!AUTH_METHODS.phone && <span className=\"rounded-full bg-bg px-2 py-0.5 text-[10px] text-ink-soft ring-1 ring-line\">Soon</span>}\n          </button>\n          {phoneOpen && AUTH_METHODS.phone && <PhoneForm onDone={() => done(\"Signed in · your progress is saved\")} />}\n          <div className=\"flex items-center gap-3 py-2 text-xs text-ink-soft\">\n            <span className=\"h-px flex-1 bg-line\" /> or with email <span className=\"h-px flex-1 bg-line\" />\n          </div>\n        </div>\n      )}\n\n      <EmailForm mode={mode} onMode={setMode} onDone={done} />\n\n      <p className=\"flex items-start gap-2 px-1 text-xs text-ink-soft\">\n        <Lock size={13} className=\"mt-0.5 shrink-0 text-forest\" />\n        Your check-ins and notes are private. Kayani staff can&apos;t read them, and we never use them for adverts.\n      </p>\n    </Shell>\n  );\n}\n\nfunction EmailForm({ mode, onMode, onDone }: { mode: Mode; onMode: (m: Mode) => void; onDone: (msg: string) => void }) {\n  const [email, setEmail] = useState(\"\");\n  const [password, setPassword] = useState(\"\");\n  const [show, setShow] = useState(false);\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const [sent, setSent] = useState<string | null>(null);\n\n  async function submit(e: React.FormEvent) {\n    e.preventDefault();\n    setBusy(true);\n    setError(null);\n    if (mode === \"reset\") {\n      const r = await account.resetPassword(email);\n      setBusy(false);\n      if (r.error) return setError(r.error);\n      return setSent(\"If that email has an account, a reset link is on its way. Check your inbox.\");\n    }\n    const r = mode === \"signup\" ? await account.signUpEmail(email, password) : await account.signInEmail(email, password);\n    setBusy(false);\n    if (r.error) return setError(r.error);\n    if (r.needsConfirm) return setSent(\"Almost done. We sent you an email: tap the link in it to finish creating your account.\");\n    onDone(mode === \"signup\" ? \"Account created · your progress is saved\" : \"Welcome back\");\n  }\n\n  if (sent) {\n    return (\n      <div className=\"rounded-3xl bg-mint/60 p-5 text-sm text-forest-deep\">\n        <Mail size={20} className=\"mb-2 text-forest\" />\n        {sent}\n        <button onClick={() => { setSent(null); onMode(\"login\"); }} className=\"mt-3 block font-semibold text-forest\">\n          Back to log in\n        </button>\n      </div>\n    );\n  }\n\n  return (\n    <form onSubmit={submit} className=\"space-y-3\">\n      <label className=\"block\">\n        <span className=\"text-xs font-semibold text-ink-soft\">Email</span>\n        <input type=\"email\" autoComplete=\"email\" required value={email} onChange={(e) => setEmail(e.target.value)} className={input} />\n      </label>\n      {mode !== \"reset\" && (\n        <label className=\"block\">\n          <span className=\"text-xs font-semibold text-ink-soft\">Password</span>\n          <div className=\"relative\">\n            <input\n              type={show ? \"text\" : \"password\"}\n              autoComplete={mode === \"signup\" ? \"new-password\" : \"current-password\"}\n              required\n              minLength={mode === \"signup\" ? 8 : undefined}\n              value={password}\n              onChange={(e) => setPassword(e.target.value)}\n              className={`${input} pr-11`}\n            />\n            <button type=\"button\" onClick={() => setShow((s) => !s)} aria-label={show ? \"Hide password\" : \"Show password\"} className=\"absolute inset-y-0 right-0 mt-1 flex w-11 items-center justify-center text-ink-soft\">\n              {show ? <EyeOff size={16} /> : <Eye size={16} />}\n            </button>\n          </div>\n          {mode === \"signup\" && <span className=\"mt-1 block text-[11px] text-ink-soft\">At least 8 characters.</span>}\n        </label>\n      )}\n      {error && (\n        <p role=\"alert\" className=\"rounded-2xl bg-red-50 px-3 py-2 text-sm text-red-700\">\n          {error}\n        </p>\n      )}\n      <button disabled={busy} className=\"flex w-full items-center justify-center gap-2 rounded-full bg-forest py-3.5 text-sm font-semibold text-white transition-transform active:scale-[0.98] disabled:opacity-60\">\n        {busy && <Loader2 size={16} className=\"animate-spin\" />}\n        {mode === \"signup\" ? \"Create account\" : mode === \"login\" ? \"Log in\" : \"Send reset link\"}\n      </button>\n      <div className=\"flex justify-between text-xs font-semibold text-forest\">\n        {mode === \"login\" && (\n          <button type=\"button\" onClick={() => onMode(\"reset\")}>\n            Forgot password?\n          </button>\n        )}\n        {mode === \"reset\" && (\n          <button type=\"button\" onClick={() => onMode(\"login\")}>\n            Back to log in\n          </button>\n        )}\n      </div>\n    </form>\n  );\n}\n\nfunction PhoneForm({ onDone }: { onDone: () => void }) {\n  const [phone, setPhone] = useState(\"\");\n  const [sentTo, setSentTo] = useState<string | null>(null);\n  const [code, setCode] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  async function send(e: React.FormEvent) {\n    e.preventDefault();\n    setBusy(true);\n    setError(null);\n    const r = await account.sendPhoneCode(phone);\n    setBusy(false);\n    if (r.error) return setError(r.error);\n    setSentTo(r.phone ?? null);\n  }\n  async function verify(e: React.FormEvent) {\n    e.preventDefault();\n    if (!sentTo) return;\n    setBusy(true);\n    setError(null);\n    const r = await account.verifyPhoneCode(sentTo, code);\n    setBusy(false);\n    if (r.error) return setError(r.error);\n    onDone();\n  }\n\n  return (\n    <form onSubmit={sentTo ? verify : send} className=\"space-y-3 rounded-3xl bg-surface p-4 ring-1 ring-line\">\n      {sentTo ? (\n        <label className=\"block\">\n          <span className=\"text-xs font-semibold text-ink-soft\">Code sent by SMS to {sentTo}</span>\n          <input inputMode=\"numeric\" autoComplete=\"one-time-code\" maxLength={6} value={code} onChange={(e) => setCode(e.target.value.replace(/\\D/g, \"\"))} className={`${input} text-center text-lg tracking-[0.5em]`} />\n        </label>\n      ) : (\n        <label className=\"block\">\n          <span className=\"text-xs font-semibold text-ink-soft\">Mobile number</span>\n          <input type=\"tel\" inputMode=\"tel\" autoComplete=\"tel\" placeholder=\"0712 345 678\" value={phone} onChange={(e) => setPhone(e.target.value)} className={input} />\n        </label>\n      )}\n      {error && <p role=\"alert\" className=\"rounded-2xl bg-red-50 px-3 py-2 text-sm text-red-700\">{error}</p>}\n      <button disabled={busy} className=\"flex w-full items-center justify-center gap-2 rounded-full bg-forest py-3 text-sm font-semibold text-white disabled:opacity-60\">\n        {busy && <Loader2 size={16} className=\"animate-spin\" />}\n        {sentTo ? \"Confirm code\" : \"Send me a code\"}\n      </button>\n      {sentTo && (\n        <button type=\"button\" onClick={() => { setSentTo(null); setCode(\"\"); }} className=\"w-full text-xs font-semibold text-forest\">\n          Use a different number\n        </button>\n      )}\n    </form>\n  );\n}\n\nfunction Shell({ children }: { children: React.ReactNode }) {\n  return (\n    <div className=\"stagger space-y-5\">\n      <Link href=\"/me\" className=\"flex items-center gap-1 text-sm text-ink-soft\">\n        <ArrowLeft size={16} /> Me\n      </Link>\n      {children}\n    </div>\n  );\n}\n\nfunction GoogleMark() {\n  return (\n    <svg width=\"18\" height=\"18\" viewBox=\"0 0 48 48\" aria-hidden>\n      <path fill=\"#FFC107\" d=\"M43.6 20.5H42V20H24v8h11.3C33.7 32.7 29.2 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34 6.1 29.3 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.4-.4-3.5z\" />\n      <path fill=\"#FF3D00\" d=\"M6.3 14.7l6.6 4.8C14.7 15.1 19 12 24 12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34 6.1 29.3 4 24 4 16.3 4 9.7 8.3 6.3 14.7z\" />\n      <path fill=\"#4CAF50\" d=\"M24 44c5.2 0 9.9-2 13.4-5.2l-6.2-5.2C29.2 35.1 26.7 36 24 36c-5.2 0-9.6-3.3-11.3-8l-6.5 5C9.5 39.6 16.2 44 24 44z\" />\n      <path fill=\"#1976D2\" d=\"M43.6 20.5H42V20H24v8h11.3c-.8 2.2-2.2 4.2-4.1 5.6l6.2 5.2C37 39.2 44 34 44 24c0-1.3-.1-2.4-.4-3.5z\" />\n    </svg>\n  );\n}\n\nconst input = \"mt-1 w-full rounded-2xl bg-surface px-4 py-3 text-sm outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\";\n",
  "src/components/TabSwipe.tsx": "\"use client\";\n\n// Swipe left / right on a main tab page to move to the next / previous tab.\n// The page follows the finger a little, and the glass tab-bar bubble slides along with it.\n// Ignored when the finger starts on something that scrolls sideways, a text box, a popup,\n// or the very edge of the screen (where the phone's own \"back\" gesture lives).\n\nimport { useEffect } from \"react\";\nimport { usePathname, useRouter } from \"next/navigation\";\nimport { isSwipe, isTabRoot, slideDirection, swipeTarget, TAB_PATHS, tabFor } from \"@/lib/tabs\";\n\nconst EDGE = 22;\n\nfunction startsOnSomethingSideways(target: EventTarget | null): boolean {\n  let el = target instanceof Element ? target : null;\n  if (el?.closest(\"input, textarea, select, [role=dialog], [data-no-swipe]\")) return true;\n  while (el && el !== document.body) {\n    if (el instanceof HTMLElement && el.scrollWidth > el.clientWidth + 2) {\n      const ox = getComputedStyle(el).overflowX;\n      if (ox === \"auto\" || ox === \"scroll\") return true;\n    }\n    el = el.parentElement;\n  }\n  return false;\n}\n\nexport default function TabSwipe() {\n  const pathname = usePathname();\n  const router = useRouter();\n\n  useEffect(() => {\n    if (!isTabRoot(pathname)) return;\n    const current = tabFor(pathname);\n    const reduce = window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n    const root = document.documentElement;\n    let start: { x: number; y: number; t: number } | null = null;\n    let mode: \"undecided\" | \"swipe\" | \"scroll\" = \"undecided\";\n    let dx = 0;\n\n    const page = () => document.getElementById(\"tab-page\");\n    const setDrag = (px: number) => {\n      const w = window.innerWidth;\n      const blocked = swipeTarget(current, px) === null;\n      const shown = blocked ? px * 0.15 : px * 0.4; // rubber band at the ends\n      const p = page();\n      if (p && !reduce) {\n        p.style.transform = `translateX(${shown}px)`;\n        p.style.opacity = String(1 - Math.min(Math.abs(shown) / w, 0.3));\n      }\n      root.style.setProperty(\"--tab-drag\", String(blocked ? 0 : -px / w));\n    };\n    const reset = (animate: boolean) => {\n      const p = page();\n      root.classList.remove(\"tab-swiping\");\n      root.style.setProperty(\"--tab-drag\", \"0\");\n      if (!p) return;\n      p.style.transition = animate ? \"transform 0.3s cubic-bezier(0.2,0.8,0.2,1), opacity 0.3s\" : \"\";\n      p.style.transform = \"\";\n      p.style.opacity = \"\";\n      if (animate) setTimeout(() => p && (p.style.transition = \"\"), 320);\n    };\n\n    const onStart = (e: TouchEvent) => {\n      if (e.touches.length !== 1) return;\n      const t = e.touches[0];\n      if (t.clientX < EDGE || t.clientX > window.innerWidth - EDGE) return;\n      if (document.querySelector(\"[role=dialog]\") || startsOnSomethingSideways(e.target)) return;\n      start = { x: t.clientX, y: t.clientY, t: performance.now() };\n      mode = \"undecided\";\n      dx = 0;\n    };\n    const onMove = (e: TouchEvent) => {\n      if (!start) return;\n      const t = e.touches[0];\n      dx = t.clientX - start.x;\n      const dy = t.clientY - start.y;\n      if (mode === \"undecided\" && (Math.abs(dx) > 10 || Math.abs(dy) > 10)) {\n        mode = Math.abs(dx) > Math.abs(dy) * 1.2 ? \"swipe\" : \"scroll\";\n        if (mode === \"swipe\") root.classList.add(\"tab-swiping\");\n      }\n      if (mode === \"swipe\") setDrag(dx);\n    };\n    const onEnd = (e: TouchEvent) => {\n      if (!start) return;\n      const t = e.changedTouches[0];\n      const dy = t.clientY - start.y;\n      const ms = performance.now() - start.t;\n      const target = mode === \"swipe\" && isSwipe(dx, dy, ms, window.innerWidth) ? swipeTarget(current, dx) : null;\n      start = null;\n      if (target === null) return reset(mode === \"swipe\");\n      slideDirection.set(target > current ? \"left\" : \"right\");\n      root.classList.remove(\"tab-swiping\");\n      root.style.setProperty(\"--tab-drag\", \"0\");\n      router.push(TAB_PATHS[target]);\n    };\n\n    window.addEventListener(\"touchstart\", onStart, { passive: true });\n    window.addEventListener(\"touchmove\", onMove, { passive: true });\n    window.addEventListener(\"touchend\", onEnd);\n    window.addEventListener(\"touchcancel\", () => reset(true));\n    return () => {\n      window.removeEventListener(\"touchstart\", onStart);\n      window.removeEventListener(\"touchmove\", onMove);\n      window.removeEventListener(\"touchend\", onEnd);\n      reset(false);\n    };\n  }, [pathname, router]);\n\n  return null;\n}\n",
  "src/components/account/AccountCard.tsx": "\"use client\";\n\nimport { useState, useSyncExternalStore } from \"react\";\nimport Link from \"next/link\";\nimport { CloudCheck, CloudOff, Loader2, LogOut, UserPlus, UserX } from \"lucide-react\";\nimport Sheet from \"@/components/motion/Sheet\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { account, accountLabel, type AccountState } from \"@/lib/account/useAccount\";\nimport { flushSync, stopSync, syncStatus } from \"@/lib/account/sync\";\n\nconst SERVER = { status: \"idle\" as const, lastSaved: null };\n\nexport default function AccountCard({ acc }: { acc: AccountState }) {\n  const showToast = useToast();\n  const sync = useSyncExternalStore(syncStatus.subscribe, syncStatus.get, () => SERVER);\n  const [sheet, setSheet] = useState<\"signout\" | \"delete\" | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  if (acc.status === \"loading\") return <div className=\"h-28 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />;\n\n  if (acc.status !== \"signedIn\") {\n    return (\n      <section className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n        <div className=\"flex gap-3\">\n          <UserPlus size={18} className=\"mt-0.5 shrink-0 text-forest\" />\n          <div className=\"min-w-0 flex-1\">\n            <p className=\"font-semibold\">You&apos;re a guest</p>\n            <p className=\"mt-1 text-sm text-ink-soft\">\n              Your progress is saved on this phone only. Create a free account to keep it safe, even if you change phones.\n            </p>\n            {acc.status === \"guest\" && (\n              <div className=\"mt-4 flex gap-2\">\n                <Link href=\"/account\" className=\"flex-1 rounded-full bg-forest py-3 text-center text-sm font-semibold text-white\">\n                  Create account\n                </Link>\n                <Link href=\"/account?mode=login\" className=\"flex-1 rounded-full py-3 text-center text-sm font-semibold ring-1 ring-line\">\n                  Log in\n                </Link>\n              </div>\n            )}\n          </div>\n        </div>\n      </section>\n    );\n  }\n\n  async function signOut() {\n    setBusy(true);\n    await flushSync();\n    stopSync({ clearPhone: true }); // his data stays in his account, not on this phone\n    await account.signOut();\n    setBusy(false);\n    setSheet(null);\n    showToast(\"Signed out\");\n  }\n\n  async function deleteAccount() {\n    setBusy(true);\n    setError(null);\n    stopSync({ clearPhone: false });\n    const r = await account.deleteAccount();\n    if (r.error) {\n      setBusy(false);\n      return setError(r.error);\n    }\n    stopSync({ clearPhone: true });\n    window.location.href = \"/\";\n  }\n\n  const savedText =\n    sync.status === \"syncing\"\n      ? \"Saving…\"\n      : sync.status === \"offline\"\n        ? \"Offline. Changes will save when you're back online.\"\n        : sync.status === \"error\"\n          ? \"Couldn't save just now. We'll try again.\"\n          : \"Your progress is saved to your account.\";\n\n  return (\n    <section className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n      <p className=\"text-xs font-semibold uppercase tracking-wider text-ink-soft\">Your account</p>\n      <p className=\"mt-1 truncate font-semibold\">{accountLabel(acc.user)}</p>\n      <p className={`mt-2 flex items-center gap-1.5 text-xs ${sync.status === \"offline\" || sync.status === \"error\" ? \"text-amber-800\" : \"text-forest\"}`}>\n        {sync.status === \"syncing\" ? <Loader2 size={14} className=\"animate-spin\" /> : sync.status === \"offline\" || sync.status === \"error\" ? <CloudOff size={14} /> : <CloudCheck size={14} />}\n        {savedText}\n      </p>\n      <div className=\"mt-4 flex gap-2\">\n        <button onClick={() => setSheet(\"signout\")} className=\"flex flex-1 items-center justify-center gap-1.5 rounded-full py-2.5 text-sm font-semibold ring-1 ring-line\">\n          <LogOut size={14} /> Sign out\n        </button>\n        <button onClick={() => setSheet(\"delete\")} className=\"flex flex-1 items-center justify-center gap-1.5 rounded-full py-2.5 text-sm font-semibold text-red-700 ring-1 ring-line\">\n          <UserX size={14} /> Delete account\n        </button>\n      </div>\n\n      <Sheet open={sheet === \"signout\"} onClose={() => setSheet(null)} title=\"Sign out?\">\n        <p className=\"text-sm text-ink-soft\">\n          Your progress stays safe in your account. It will be removed from this phone, so nobody else using it can see it.\n        </p>\n        <button onClick={signOut} disabled={busy} className=\"mt-4 flex w-full items-center justify-center gap-2 rounded-full bg-forest py-3 text-sm font-semibold text-white disabled:opacity-60\">\n          {busy && <Loader2 size={14} className=\"animate-spin\" />} Sign out\n        </button>\n      </Sheet>\n\n      <Sheet open={sheet === \"delete\"} onClose={() => setSheet(null)} title=\"Delete your account?\">\n        <p className=\"text-sm text-ink-soft\">\n          This deletes your login and everything saved in it: points, badges, check-ins, sleep and water records. It can&apos;t be\n          undone.\n        </p>\n        {error && <p className=\"mt-2 text-sm text-red-700\">{error}</p>}\n        <div className=\"mt-4 grid grid-cols-2 gap-2\">\n          <button onClick={() => setSheet(null)} className=\"rounded-full py-3 text-sm font-semibold ring-1 ring-line\">\n            Keep it\n          </button>\n          <button onClick={deleteAccount} disabled={busy} className=\"flex items-center justify-center gap-2 rounded-full bg-red-700 py-3 text-sm font-semibold text-white disabled:opacity-60\">\n            {busy && <Loader2 size={14} className=\"animate-spin\" />} Delete\n          </button>\n        </div>\n      </Sheet>\n    </section>\n  );\n}\n",
  "src/components/account/AccountInvite.tsx": "\"use client\";\n\n// A friendly \"create a free account\" invite at the right moments, never more than once per moment:\n// - first-points: he just earned his first points\n// - first-save: he saved his first guide\n// Only shown to guests. He can always say \"Not now\".\n\nimport { useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport { ShieldCheck } from \"lucide-react\";\nimport Sheet from \"@/components/motion/Sheet\";\nimport { useAccount } from \"@/lib/account/useAccount\";\n\nexport type InviteReason = \"first-points\" | \"first-save\";\nconst EVENT = \"ms-account-invite\";\nconst seenKey = (r: InviteReason) => `ms_invite_${r}`;\n\nconst COPY: Record<InviteReason, { title: string; text: string }> = {\n  \"first-points\": {\n    title: \"Nice start! 🎉\",\n    text: \"You just earned your first points. Create a free account so your progress is safe, even if you change phones.\",\n  },\n  \"first-save\": {\n    title: \"Saved for later\",\n    text: \"Create a free account and your saved guides follow you to any phone.\",\n  },\n};\n\n/** Ask for the invite from anywhere. It only appears if he's a guest and hasn't seen it for this reason. */\nexport function inviteToAccount(reason: InviteReason) {\n  try {\n    if (localStorage.getItem(seenKey(reason))) return;\n  } catch {\n    return;\n  }\n  window.dispatchEvent(new CustomEvent(EVENT, { detail: reason }));\n}\n\n/** Mounted once in the app layout. */\nexport default function AccountInviteSheet() {\n  const acc = useAccount();\n  const [reason, setReason] = useState<InviteReason | null>(null);\n\n  useEffect(() => {\n    if (acc.status !== \"guest\") return;\n    const onInvite = (e: Event) => {\n      const r = (e as CustomEvent<InviteReason>).detail;\n      try {\n        localStorage.setItem(seenKey(r), new Date().toISOString());\n      } catch {}\n      // Let the toast for what he just did show first\n      setTimeout(() => setReason(r), 900);\n    };\n    window.addEventListener(EVENT, onInvite);\n    return () => window.removeEventListener(EVENT, onInvite);\n  }, [acc.status]);\n\n  const copy = reason ? COPY[reason] : null;\n  return (\n    <Sheet open={reason !== null} onClose={() => setReason(null)} title={copy?.title ?? \"\"}>\n      <div className=\"flex gap-3\">\n        <ShieldCheck size={20} className=\"mt-0.5 shrink-0 text-forest\" />\n        <p className=\"text-sm text-ink-soft\">{copy?.text}</p>\n      </div>\n      <div className=\"mt-5 space-y-2\">\n        <Link\n          href=\"/account\"\n          onClick={() => setReason(null)}\n          className=\"block w-full rounded-full bg-forest py-3 text-center text-sm font-semibold text-white\"\n        >\n          Create free account\n        </Link>\n        <button onClick={() => setReason(null)} className=\"w-full py-2 text-sm font-semibold text-ink-soft\">\n          Not now\n        </button>\n      </div>\n    </Sheet>\n  );\n}\n",
  "src/components/account/AccountSync.tsx": "\"use client\";\n\nimport { useEffect } from \"react\";\nimport { useAccount } from \"@/lib/account/useAccount\";\nimport { startSync, stopSync } from \"@/lib/account/sync\";\n\n/** Invisible: when a man is signed in, keeps his phone and account in step. */\nexport default function AccountSync() {\n  const acc = useAccount();\n  const userId = acc.status === \"signedIn\" ? acc.user.id : null;\n  useEffect(() => {\n    if (userId) void startSync(userId);\n    else if (acc.status === \"guest\") stopSync({ clearPhone: false });\n  }, [userId, acc.status]);\n  return null;\n}\n",
  "src/components/account/SaveProgressCard.tsx": "\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport { inviteToAccount } from \"./AccountInvite\";\nimport Link from \"next/link\";\nimport { ShieldCheck, X } from \"lucide-react\";\nimport { useAccount } from \"@/lib/account/useAccount\";\n\nconst KEY = \"ms_nudge_account\";\n\n/** A gentle invite to create an account, once he has some progress worth keeping. He can dismiss it. */\nexport default function SaveProgressCard({ points }: { points: number }) {\n  const acc = useAccount();\n  const [hidden, setHidden] = useState(() => {\n    try {\n      return typeof window !== \"undefined\" && localStorage.getItem(KEY) === \"dismissed\";\n    } catch {\n      return false;\n    }\n  });\n  // The moment he earns his first points, invite him once\n  useEffect(() => {\n    if (acc.status === \"guest\" && points > 0) inviteToAccount(\"first-points\");\n  }, [acc.status, points]);\n\n  if (acc.status !== \"guest\" || points < 20 || hidden) return null;\n\n  return (\n    <section className=\"relative flex gap-3 rounded-3xl bg-mint/60 p-5\">\n      <ShieldCheck size={20} className=\"mt-0.5 shrink-0 text-forest\" />\n      <div className=\"min-w-0 flex-1 pr-6\">\n        <p className=\"font-semibold text-forest-deep\">Keep your {points} points safe</p>\n        <p className=\"mt-1 text-sm text-forest\">Create a free account so you don&apos;t lose your progress if you change or lose your phone.</p>\n        <Link href=\"/account\" className=\"mt-3 inline-block rounded-full bg-forest px-4 py-2 text-sm font-semibold text-white\">\n          Create free account\n        </Link>\n      </div>\n      <button\n        aria-label=\"Not now\"\n        onClick={() => {\n          setHidden(true);\n          try {\n            localStorage.setItem(KEY, \"dismissed\");\n          } catch {}\n        }}\n        className=\"absolute right-3 top-3 rounded-full p-1.5 text-forest\"\n      >\n        <X size={16} />\n      </button>\n    </section>\n  );\n}\n\n/** Small line under the Man tab saying where his data is kept. */\nexport function WhereSavedNote() {\n  const acc = useAccount();\n  return (\n    <p className=\"px-2 pt-2 text-center text-[11px] text-ink-soft\">\n      {acc.status === \"signedIn\"\n        ? \"Saved privately to your account.\"\n        : \"Saved on this phone for now. Your records move to your account when you sign up.\"}\n    </p>\n  );\n}\n",
  "src/lib/account/merge.test.ts": "import { describe, expect, it } from \"vitest\";\nimport { mergeFeed, mergeProgress, mergeSocial, normalizeTzPhone } from \"./merge\";\nimport type { TrackingRecord } from \"../progress/types\";\nimport type { SocialDB } from \"../social/store\";\n\nconst rec = (id: string, value: number, updatedAt: string): TrackingRecord => ({\n  id, userId: \"local\", metric: \"water\", value, unit: \"ml\", source: \"manual\",\n  recordedAt: \"2026-10-13T08:00:00Z\", localDate: \"2026-10-13\", createdAt: \"2026-10-13T08:00:00Z\", updatedAt,\n});\nconst emptySocial: SocialDB = { bookmarks: {}, interests: [], nickname: \"\", posts: [], replies: [], reactions: {}, reports: {} };\n\ndescribe(\"merging phone data with his account\", () => {\n  it(\"keeps records from both sides and the newest edit of the same record\", () => {\n    const local = { records: [rec(\"a\", 250, \"2026-10-13T09:00:00Z\"), rec(\"b\", 500, \"2026-10-13T09:00:00Z\")], goals: [] };\n    const remote = { records: [rec(\"a\", 300, \"2026-10-13T10:00:00Z\"), rec(\"c\", 750, \"2026-10-12T09:00:00Z\")], goals: [] };\n    const m = mergeProgress(local, remote, \"user-1\");\n    expect(m.records.map((r) => [r.id, r.value]).sort()).toEqual([[\"a\", 300], [\"b\", 500], [\"c\", 750]]);\n    expect(m.records.every((r) => r.userId === \"user-1\")).toBe(true);\n  });\n  it(\"keeps the goal he changed most recently, and his account's goal over a default\", () => {\n    const def = { metric: \"water\" as const, target: 2500, unit: \"ml\" as const, period: \"day\" as const, direction: \"increase\" as const, updatedAt: \"\" };\n    const set = { ...def, target: 3000, updatedAt: \"2026-10-10T00:00:00Z\" };\n    expect(mergeProgress({ records: [], goals: [def] }, { goals: [set] }).goals[0].target).toBe(3000);\n  });\n  it(\"works when the account is empty (first sign-in)\", () => {\n    const local = { records: [rec(\"a\", 250, \"x\")], goals: [] };\n    expect(mergeProgress(local, null).records).toHaveLength(1);\n  });\n  it(\"merges daily choices and lessons from both phones\", () => {\n    const local = { days: { \"2026-10-13\": { walk: { status: \"done\" as const, at: \"2026-10-13T10:00:00Z\" } } }, lessons: { l1: { localDate: \"2026-10-13\", at: \"2026-10-13T10:00:00Z\" } }, settings: { discreet: false } };\n    const remote = { days: { \"2026-10-13\": { walk: { status: \"later\" as const, at: \"2026-10-13T08:00:00Z\" }, meal: { status: \"done\" as const, at: \"2026-10-13T08:00:00Z\" } } }, lessons: { l1: { localDate: \"2026-10-12\", at: \"2026-10-12T10:00:00Z\" } }, settings: { discreet: true } };\n    const m = mergeFeed(local, remote);\n    expect(m.days[\"2026-10-13\"].walk.status).toBe(\"done\");\n    expect(m.days[\"2026-10-13\"].meal.status).toBe(\"done\");\n    expect(m.lessons.l1.localDate).toBe(\"2026-10-12\");\n    expect(m.settings.discreet).toBe(true);\n  });\n  it(\"merges bookmarks, topics and reactions, keeping his name from this phone\", () => {\n    const local = { ...emptySocial, bookmarks: { a: \"1\" }, interests: [\"libido\" as const], nickname: \"Juma\", reactions: { p1: [\"helpful\" as never] } };\n    const remote = { ...emptySocial, bookmarks: { b: \"2\" }, interests: [\"libido\" as const, \"confidence\" as const], nickname: \"J\", reactions: { p1: [\"support\" as never] } };\n    const m = mergeSocial(local, remote);\n    expect(Object.keys(m.bookmarks).sort()).toEqual([\"a\", \"b\"]);\n    expect(m.interests).toEqual([\"libido\", \"confidence\"]);\n    expect(m.nickname).toBe(\"Juma\");\n    expect(m.reactions.p1.sort()).toEqual([\"helpful\", \"support\"]);\n    expect(mergeSocial({ ...emptySocial }, remote).nickname).toBe(\"J\");\n  });\n});\n\ndescribe(\"Tanzanian phone numbers\", () => {\n  it(\"accepts the usual ways people write them\", () => {\n    for (const p of [\"0712 345 678\", \"+255712345678\", \"255 712 345 678\", \"712345678\", \"0654-123-456\"]) {\n      expect(normalizeTzPhone(p), p).toMatch(/^\\+255[67]\\d{8}$/);\n    }\n    expect(normalizeTzPhone(\"0712 345 678\")).toBe(\"+255712345678\");\n  });\n  it(\"rejects numbers that aren't Tanzanian mobiles\", () => {\n    for (const p of [\"12345\", \"0812345678\", \"+254712345678\", \"07123456789\"]) expect(normalizeTzPhone(p), p).toBeNull();\n  });\n});\n",
  "src/lib/account/merge.ts": "// Combines what's on this phone with what's saved in his account, without losing either.\n// Used when he signs in (e.g. guest progress + an account he made on another phone).\n// Pure functions — easy to test.\n\nimport type { FeedDB } from \"../feed/store\";\nimport type { SocialDB } from \"../social/store\";\nimport type { Goal, TrackingRecord } from \"../progress/types\";\n\nexport type ProgressDB = { records: TrackingRecord[]; goals: Goal[] };\n\n/** Keep one of each id; if both sides have it, keep the most recently changed. */\nfunction byIdNewest<T extends { id: string }>(a: T[], b: T[], stamp: (x: T) => string): T[] {\n  const map = new Map<string, T>();\n  for (const x of [...a, ...b]) {\n    const have = map.get(x.id);\n    if (!have || stamp(x) > stamp(have)) map.set(x.id, x);\n  }\n  return [...map.values()];\n}\n\nexport function mergeProgress(local: ProgressDB, remote: Partial<ProgressDB> | null, userId?: string): ProgressDB {\n  const r = { records: remote?.records ?? [], goals: remote?.goals ?? [] };\n  const records = byIdNewest(local.records, r.records, (x) => x.updatedAt ?? \"\")\n    .map((x) => (userId ? { ...x, userId } : x))\n    .sort((a, b) => a.recordedAt.localeCompare(b.recordedAt));\n  const goals = new Map<string, Goal>();\n  for (const g of [...local.goals, ...r.goals]) {\n    const have = goals.get(g.metric);\n    if (!have || (g.updatedAt ?? \"\") > (have.updatedAt ?? \"\")) goals.set(g.metric, g);\n  }\n  return { records, goals: [...goals.values()] };\n}\n\nexport function mergeFeed(local: FeedDB, remote: Partial<FeedDB> | null): FeedDB {\n  const days: FeedDB[\"days\"] = {};\n  for (const src of [local.days, remote?.days ?? {}]) {\n    for (const [day, choices] of Object.entries(src)) {\n      days[day] = { ...days[day] };\n      for (const [id, c] of Object.entries(choices)) {\n        const have = days[day][id];\n        if (!have || c.at > have.at) days[day][id] = c;\n      }\n    }\n  }\n  const lessons: FeedDB[\"lessons\"] = { ...(remote?.lessons ?? {}) };\n  for (const [id, l] of Object.entries(local.lessons)) {\n    if (!lessons[id] || l.at < lessons[id].at) lessons[id] = l; // first time he read it\n  }\n  return {\n    days,\n    lessons,\n    settings: { discreet: Boolean(local.settings.discreet || remote?.settings?.discreet) },\n  };\n}\n\nexport function mergeSocial(local: SocialDB, remote: Partial<SocialDB> | null): SocialDB {\n  const r: SocialDB = { bookmarks: {}, interests: [], nickname: \"\", posts: [], replies: [], reactions: {}, reports: {}, ...remote };\n  const reactions: SocialDB[\"reactions\"] = { ...r.reactions };\n  for (const [id, kinds] of Object.entries(local.reactions)) reactions[id] = [...new Set([...(reactions[id] ?? []), ...kinds])];\n  return {\n    bookmarks: { ...r.bookmarks, ...local.bookmarks },\n    interests: [...new Set([...r.interests, ...local.interests])],\n    nickname: local.nickname || r.nickname,\n    posts: byIdNewest(r.posts, local.posts, (p) => p.createdAt),\n    replies: byIdNewest(r.replies, local.replies, (p) => p.createdAt),\n    reactions,\n    reports: { ...r.reports, ...local.reports },\n  };\n}\n\n/** Tanzanian phone numbers in any common format → +255XXXXXXXXX, or null if it isn't one. */\nexport function normalizeTzPhone(input: string): string | null {\n  const digits = input.replace(/[^\\d+]/g, \"\");\n  const m = /^(?:\\+?255|0)?([67]\\d{8})$/.exec(digits);\n  return m ? `+255${m[1]}` : null;\n}\n",
  "src/lib/account/sync.ts": "\"use client\";\n\n// Keeps his phone and his account in step.\n// - When he signs in: phone data + account data are merged (nothing lost), then saved to both.\n// - After that: every change he makes is saved to his account a moment later.\n// - Offline: changes wait, and are saved when the connection comes back.\n\nimport { getSupabase } from \"../supabase/client\";\nimport { feedSync } from \"../feed/store\";\nimport { progressSync } from \"../progress/store\";\nimport { socialSync } from \"../social/store\";\nimport { mergeFeed, mergeProgress, mergeSocial } from \"./merge\";\n\nexport type Kind = \"progress\" | \"feed\" | \"social\";\nexport type SyncStatus = \"idle\" | \"syncing\" | \"saved\" | \"offline\" | \"error\";\n\n/* eslint-disable @typescript-eslint/no-explicit-any */\nconst STORES: Record<Kind, { get: () => any; replace: (db: any) => void; clear: () => void; onChange: (cb: () => void) => () => void; merge: (local: any, remote: any, userId: string) => any }> = {\n  progress: { ...progressSync, merge: (l, r, u) => mergeProgress(l, r, u) },\n  feed: { ...feedSync, merge: (l, r) => mergeFeed(l, r) },\n  social: { ...socialSync, merge: (l, r) => mergeSocial(l, r) },\n};\n/* eslint-enable @typescript-eslint/no-explicit-any */\nconst KINDS = Object.keys(STORES) as Kind[];\n\n// One snapshot object per change (screens compare it by reference)\nlet snapshot: { status: SyncStatus; lastSaved: string | null } = { status: \"idle\", lastSaved: null };\nconst statusListeners = new Set<() => void>();\nfunction setStatus(s: SyncStatus) {\n  snapshot = { status: s, lastSaved: s === \"saved\" ? new Date().toISOString() : snapshot.lastSaved };\n  statusListeners.forEach((l) => l());\n}\nexport const syncStatus = {\n  get: () => snapshot,\n  subscribe(cb: () => void) {\n    statusListeners.add(cb);\n    return () => {\n      statusListeners.delete(cb);\n    };\n  },\n};\n\nlet current: { userId: string; stop: () => void } | null = null;\nconst pending = new Set<Kind>();\nlet timer: ReturnType<typeof setTimeout> | null = null;\n\nasync function push(userId: string, kinds: Kind[]) {\n  const sb = getSupabase();\n  if (!sb || kinds.length === 0) return;\n  setStatus(\"syncing\");\n  const rows = kinds.map((kind) => ({ user_id: userId, kind, data: STORES[kind].get() }));\n  const { error } = await sb.from(\"user_data\").upsert(rows);\n  if (error) {\n    kinds.forEach((k) => pending.add(k));\n    setStatus(navigator.onLine ? \"error\" : \"offline\");\n    return;\n  }\n  setStatus(\"saved\");\n}\n\nfunction schedule(userId: string, kind: Kind) {\n  pending.add(kind);\n  if (timer) clearTimeout(timer);\n  timer = setTimeout(() => {\n    const kinds = [...pending];\n    pending.clear();\n    void push(userId, kinds);\n  }, 1200);\n}\n\n/** Start keeping this phone and his account in step. Safe to call again for the same man. */\nexport async function startSync(userId: string): Promise<void> {\n  if (current?.userId === userId) return;\n  current?.stop();\n  const sb = getSupabase();\n  if (!sb) return;\n\n  setStatus(\"syncing\");\n  const { data, error } = await sb.from(\"user_data\").select(\"kind, data\").eq(\"user_id\", userId);\n  if (error) {\n    setStatus(navigator.onLine ? \"error\" : \"offline\");\n  } else {\n    const remote = new Map((data ?? []).map((r: { kind: Kind; data: unknown }) => [r.kind, r.data]));\n    for (const k of KINDS) STORES[k].replace(STORES[k].merge(STORES[k].get(), remote.get(k) ?? null, userId));\n    await push(userId, KINDS);\n  }\n\n  const offs = KINDS.map((k) => STORES[k].onChange(() => schedule(userId, k)));\n  const retry = () => {\n    if (pending.size) schedule(userId, [...pending][0]);\n  };\n  window.addEventListener(\"online\", retry);\n  current = {\n    userId,\n    stop: () => {\n      offs.forEach((off) => off());\n      window.removeEventListener(\"online\", retry);\n      if (timer) clearTimeout(timer);\n      pending.clear();\n    },\n  };\n  // If loading failed, try a full sync again when he's back online\n  if (error) window.addEventListener(\"online\", () => current?.userId === userId && (current.stop(), (current = null), startSync(userId)), { once: true });\n}\n\n/** Save anything waiting right now (e.g. before signing out). */\nexport async function flushSync() {\n  if (!current) return;\n  if (timer) clearTimeout(timer);\n  const kinds = [...pending];\n  pending.clear();\n  await push(current.userId, kinds);\n}\n\n/** Stop syncing. With clearPhone, his data is removed from this phone (it stays safe in his account). */\nexport function stopSync({ clearPhone }: { clearPhone: boolean }) {\n  current?.stop();\n  current = null;\n  if (clearPhone) KINDS.forEach((k) => STORES[k].clear());\n  setStatus(\"idle\");\n}\n\n/** Delete his saved data from his account (the account itself stays). */\nexport async function deleteCloudData(userId: string) {\n  const sb = getSupabase();\n  if (!sb) return;\n  const { error } = await sb.from(\"user_data\").delete().eq(\"user_id\", userId);\n  if (error) throw new Error(error.message);\n}\n",
  "src/lib/account/useAccount.ts": "\"use client\";\n\n// Is a man signed in to his own account? Sign up / log in with email, Google or phone.\n\nimport { useEffect, useState } from \"react\";\nimport type { User } from \"@supabase/supabase-js\";\nimport { getSupabase, supabaseConfigured } from \"../supabase/client\";\nimport { normalizeTzPhone } from \"./merge\";\n\nexport type AccountState =\n  | { status: \"loading\" }\n  | { status: \"unavailable\" } // Supabase not set up: guest only\n  | { status: \"guest\" }\n  | { status: \"signedIn\"; user: User };\n\n/** Which sign-in methods are switched on (set in .env.local / Vercel once each is set up in Supabase). */\nexport const AUTH_METHODS = {\n  email: true,\n  google: process.env.NEXT_PUBLIC_AUTH_GOOGLE === \"on\",\n  phone: process.env.NEXT_PUBLIC_AUTH_PHONE === \"on\",\n};\n\nexport function useAccount(): AccountState {\n  const [state, setState] = useState<AccountState>(supabaseConfigured ? { status: \"loading\" } : { status: \"unavailable\" });\n  useEffect(() => {\n    const sb = getSupabase();\n    if (!sb) return;\n    sb.auth.getSession().then(({ data }) =>\n      setState(data.session?.user ? { status: \"signedIn\", user: data.session.user } : { status: \"guest\" }),\n    );\n    const { data } = sb.auth.onAuthStateChange((_e, session) =>\n      setState(session?.user ? { status: \"signedIn\", user: session.user } : { status: \"guest\" }),\n    );\n    return () => data.subscription.unsubscribe();\n  }, []);\n  return state;\n}\n\n/** How we show who he is: email, phone, or \"Google account\". */\nexport function accountLabel(user: User): string {\n  return user.email || (user.phone ? `+${user.phone.replace(/^\\+/, \"\")}` : \"Your account\");\n}\n\nconst friendly = (message: string): string => {\n  const m = message.toLowerCase();\n  if (m.includes(\"already registered\") || m.includes(\"already been registered\")) return \"This email already has an account. Log in instead.\";\n  if (m.includes(\"invalid login\")) return \"Wrong email or password.\";\n  if (m.includes(\"email not confirmed\")) return \"Please confirm your email first. Check your inbox.\";\n  if (m.includes(\"password should be\") || m.includes(\"weak\")) return \"Choose a stronger password: at least 8 characters.\";\n  if (m.includes(\"rate limit\") || m.includes(\"too many\")) return \"Too many tries. Please wait a few minutes and try again.\";\n  if (m.includes(\"token has expired\") || m.includes(\"invalid otp\") || m.includes(\"otp\")) return \"That code is wrong or expired. Ask for a new one.\";\n  if (m.includes(\"fetch\") || m.includes(\"network\")) return \"Can't connect. Check your internet and try again.\";\n  if (m.includes(\"provider is not enabled\") || m.includes(\"unsupported provider\")) return \"This sign-in option isn't switched on yet.\";\n  return message;\n};\n\ntype Result = { error: string | null; needsConfirm?: boolean };\n\nexport const account = {\n  async signUpEmail(email: string, password: string): Promise<Result> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    if (password.length < 8) return { error: \"Use at least 8 characters for your password.\" };\n    const { data, error } = await sb.auth.signUp({ email: email.trim(), password, options: { emailRedirectTo: `${location.origin}/me` } });\n    if (error) return { error: friendly(error.message) };\n    // Supabase hides \"already registered\" by returning a user with no identities\n    if (data.user && data.user.identities?.length === 0) return { error: friendly(\"already registered\") };\n    return { error: null, needsConfirm: !data.session };\n  },\n\n  async signInEmail(email: string, password: string): Promise<Result> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    const { error } = await sb.auth.signInWithPassword({ email: email.trim(), password });\n    return { error: error ? friendly(error.message) : null };\n  },\n\n  async resetPassword(email: string): Promise<Result> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    const { error } = await sb.auth.resetPasswordForEmail(email.trim(), { redirectTo: `${location.origin}/account/new-password` });\n    return { error: error ? friendly(error.message) : null };\n  },\n\n  async setNewPassword(password: string): Promise<Result> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    if (password.length < 8) return { error: \"Use at least 8 characters for your password.\" };\n    const { error } = await sb.auth.updateUser({ password });\n    return { error: error ? friendly(error.message) : null };\n  },\n\n  async signInGoogle(): Promise<Result> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    const { error } = await sb.auth.signInWithOAuth({ provider: \"google\", options: { redirectTo: `${location.origin}/me` } });\n    return { error: error ? friendly(error.message) : null };\n  },\n\n  async sendPhoneCode(phoneInput: string): Promise<Result & { phone?: string }> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    const phone = normalizeTzPhone(phoneInput);\n    if (!phone) return { error: \"Enter a Tanzanian mobile number, e.g. 0712 345 678.\" };\n    const { error } = await sb.auth.signInWithOtp({ phone });\n    return { error: error ? friendly(error.message) : null, phone };\n  },\n\n  async verifyPhoneCode(phone: string, code: string): Promise<Result> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    const { error } = await sb.auth.verifyOtp({ phone, token: code.trim(), type: \"sms\" });\n    return { error: error ? friendly(error.message) : null };\n  },\n\n  async signOut() {\n    await getSupabase()?.auth.signOut();\n  },\n\n  async deleteAccount(): Promise<Result> {\n    const sb = getSupabase();\n    if (!sb) return { error: \"Accounts aren't available yet.\" };\n    const { error } = await sb.rpc(\"delete_my_account\");\n    if (error) return { error: friendly(error.message) };\n    await sb.auth.signOut();\n    return { error: null };\n  },\n};\n",
  "src/lib/supabase/user-data.test.ts": "// Runs the accounts migration in a real Postgres (PGlite) and checks that every man\n// can only see his own data — and that Content Studio admins can't see it either.\nimport { readFileSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { PGlite } from \"@electric-sql/pglite\";\nimport { beforeAll, describe, expect, it } from \"vitest\";\n\nconst JUMA = \"11111111-1111-1111-1111-111111111111\";\nconst ALLY = \"22222222-2222-2222-2222-222222222222\";\nconst ADMIN = \"33333333-3333-3333-3333-333333333333\";\n\nlet db: PGlite;\n\nasync function as(uid: string | null, role: \"anon\" | \"authenticated\", sql: string, params: unknown[] = []) {\n  await db.exec(`reset role; select set_config('test.uid', '${uid ?? \"\"}', false); set role ${role};`);\n  try {\n    return await db.query(sql, params);\n  } finally {\n    await db.exec(\"reset role;\");\n  }\n}\n\nconst save = (uid: string, kind: string, data: object) =>\n  as(uid, \"authenticated\", \"insert into public.user_data (user_id, kind, data) values ($1, $2, $3) on conflict (user_id, kind) do update set data = excluded.data\", [uid, kind, JSON.stringify(data)]);\n\nbeforeAll(async () => {\n  db = new PGlite();\n  await db.exec(`\n    create schema auth;\n    create table auth.users (id uuid primary key);\n    create function auth.uid() returns uuid language sql stable as\n      $$ select nullif(current_setting('test.uid', true), '')::uuid $$;\n    create schema storage;\n    create table storage.buckets (id text primary key, name text, public boolean);\n    create table storage.objects (id serial primary key, bucket_id text, name text);\n    alter table storage.objects enable row level security;\n    create role anon; create role authenticated;\n  `);\n  for (const f of [\"0001_content_studio.sql\", \"0002_user_accounts.sql\"]) {\n    const sql = readFileSync(join(process.cwd(), \"supabase/migrations\", f), \"utf8\");\n    await db.exec(sql);\n    await db.exec(sql); // safe to run twice\n  }\n  await db.exec(`\n    grant usage on schema public, auth to anon, authenticated;\n    grant select, insert, update, delete on public.user_data to anon, authenticated;\n    grant select on public.admins to authenticated;\n    grant execute on all functions in schema auth to anon, authenticated;\n    grant execute on function public.is_admin() to anon, authenticated;\n  `);\n  await db.query(\"insert into auth.users (id) values ($1), ($2), ($3)\", [JUMA, ALLY, ADMIN]);\n  await db.query(\"insert into public.admins (user_id, role) values ($1, 'owner')\", [ADMIN]);\n}, 30_000);\n\ndescribe(\"men's own data\", () => {\n  it(\"a man can save and read his own data\", async () => {\n    await save(JUMA, \"progress\", { records: [{ value: 250 }] });\n    await save(JUMA, \"progress\", { records: [{ value: 500 }] }); // update\n    const r = await as(JUMA, \"authenticated\", \"select kind, data from public.user_data\");\n    expect(r.rows).toEqual([{ kind: \"progress\", data: { records: [{ value: 500 }] } }]);\n  });\n\n  it(\"another man cannot see, change or delete it\", async () => {\n    await save(ALLY, \"social\", { nickname: \"Ally\" });\n    const seen = await as(ALLY, \"authenticated\", \"select user_id from public.user_data\");\n    expect(seen.rows).toEqual([{ user_id: ALLY }]);\n    const upd = await as(ALLY, \"authenticated\", \"update public.user_data set data = '{}' where user_id = $1 returning 1\", [JUMA]);\n    expect(upd.rows).toHaveLength(0);\n    const del = await as(ALLY, \"authenticated\", \"delete from public.user_data where user_id = $1 returning 1\", [JUMA]);\n    expect(del.rows).toHaveLength(0);\n  });\n\n  it(\"nobody can write rows in someone else's name\", async () => {\n    await expect(\n      as(ALLY, \"authenticated\", \"insert into public.user_data (user_id, kind, data) values ($1, 'feed', '{}')\", [JUMA]),\n    ).rejects.toThrow(/row-level security/);\n  });\n\n  it(\"Content Studio admins and visitors can't read men's data\", async () => {\n    expect((await as(ADMIN, \"authenticated\", \"select * from public.user_data\")).rows).toHaveLength(0);\n    expect((await as(null, \"anon\", \"select * from public.user_data\")).rows).toHaveLength(0);\n  });\n\n  it(\"rejects unknown kinds of data\", async () => {\n    await expect(save(JUMA, \"passwords\", {})).rejects.toThrow();\n  });\n\n  it(\"delete my account removes his login and all his data, and nobody else's\", async () => {\n    await as(JUMA, \"authenticated\", \"select public.delete_my_account()\");\n    const users = await db.query<{ id: string }>(\"select id from auth.users order by id\");\n    expect(users.rows.map((u) => u.id)).toEqual([ALLY, ADMIN]);\n    const left = await db.query<{ user_id: string }>(\"select user_id from public.user_data\");\n    expect(left.rows).toEqual([{ user_id: ALLY }]);\n  });\n\n  it(\"delete my account needs a signed-in man\", async () => {\n    await expect(as(null, \"anon\", \"select public.delete_my_account()\")).rejects.toThrow();\n  });\n});\n",
  "src/lib/tabs.test.ts": "import { describe, expect, it } from \"vitest\";\nimport { isSwipe, isTabRoot, swipeTarget, tabFor } from \"./tabs\";\n\ndescribe(\"tabs and swiping\", () => {\n  it(\"knows which tab a page belongs to\", () => {\n    expect(tabFor(\"/social/c/abc\")).toBe(0);\n    expect(tabFor(\"/learn/x\")).toBe(1);\n    expect(tabFor(\"/account\")).toBe(2);\n    expect(tabFor(\"/studio\")).toBe(-1);\n  });\n  it(\"only swipes on the main page of a tab\", () => {\n    expect(isTabRoot(\"/man\")).toBe(true);\n    expect(isTabRoot(\"/social/c/abc\")).toBe(false);\n  });\n  it(\"swipe left goes to the next tab, right to the previous, nothing past the ends\", () => {\n    expect(swipeTarget(0, -120)).toBe(1);\n    expect(swipeTarget(1, 120)).toBe(0);\n    expect(swipeTarget(0, 120)).toBeNull();\n    expect(swipeTarget(2, -120)).toBeNull();\n  });\n  it(\"needs a clear sideways movement, far enough or quick enough\", () => {\n    expect(isSwipe(-150, 10, 400, 390)).toBe(true); // long drag\n    expect(isSwipe(-60, 5, 150, 390)).toBe(true); // quick flick\n    expect(isSwipe(-60, 5, 500, 390)).toBe(false); // slow and short\n    expect(isSwipe(-150, 140, 300, 390)).toBe(false); // mostly scrolling down\n  });\n});\n",
  "src/lib/tabs.ts": "// The three main tabs, in order. Used by the tab bar, swipe navigation and page transitions.\n\nexport const TAB_PATHS = [\"/social\", \"/man\", \"/me\"] as const;\n\n/** Which tab a page belongs to (for highlighting the tab bar). */\nexport function tabFor(pathname: string): number {\n  if (pathname.startsWith(\"/social\")) return 0;\n  if (pathname.startsWith(\"/man\") || pathname.startsWith(\"/learn\")) return 1;\n  if (pathname.startsWith(\"/me\") || pathname.startsWith(\"/account\")) return 2;\n  return -1;\n}\n\n/** Swiping only works on the main page of each tab (not inside an article or form). */\nexport function isTabRoot(pathname: string): boolean {\n  return (TAB_PATHS as readonly string[]).includes(pathname);\n}\n\n/** Which tab a swipe leads to: swipe left (dx < 0) = next tab, swipe right = previous. Null at the ends. */\nexport function swipeTarget(current: number, dx: number): number | null {\n  const next = dx < 0 ? current + 1 : current - 1;\n  return next >= 0 && next < TAB_PATHS.length ? next : null;\n}\n\n/** Decide if a finished finger movement counts as a swipe between tabs. */\nexport function isSwipe(dx: number, dy: number, ms: number, width: number): boolean {\n  const horizontal = Math.abs(dx) > Math.abs(dy) * 1.5;\n  const far = Math.abs(dx) > width * 0.28;\n  const flick = Math.abs(dx) > 50 && ms < 280; // a quick flick counts even if short\n  return horizontal && (far || flick);\n}\n\n// The direction of the next page change, so the new page slides in from the right side.\nlet pending: \"left\" | \"right\" | null = null;\nexport const slideDirection = {\n  set(d: \"left\" | \"right\" | null) {\n    pending = d;\n  },\n  take(): \"left\" | \"right\" | null {\n    const d = pending;\n    pending = null;\n    return d;\n  },\n};\n",
  "supabase/migrations/0002_user_accounts.sql": "-- Men's Social — accounts for men: their own data, saved safely in the cloud\n-- Paste this whole file into Supabase → SQL Editor → New query → Run.\n-- Safe to run more than once.\n--\n-- PRIVACY: each man can only read and change HIS OWN rows.\n-- Admins (Content Studio) get NO access to these rows. Health journals stay private.\n\n-- ─────────────────────────────────────────────\n-- 1. His saved data: progress (water, sleep, check-ins), daily activities, social (bookmarks, topics, name)\n-- ─────────────────────────────────────────────\ncreate table if not exists public.user_data (\n  user_id uuid not null references auth.users (id) on delete cascade,\n  kind text not null check (kind in ('progress', 'feed', 'social')),\n  data jsonb not null default '{}'::jsonb check (pg_column_size(data) < 1000000),\n  updated_at timestamptz not null default now(),\n  primary key (user_id, kind)\n);\n\nalter table public.user_data enable row level security;\n\ndrop policy if exists \"men read their own data\" on public.user_data;\ncreate policy \"men read their own data\" on public.user_data\n  for select using (user_id = auth.uid());\n\ndrop policy if exists \"men add their own data\" on public.user_data;\ncreate policy \"men add their own data\" on public.user_data\n  for insert with check (user_id = auth.uid());\n\ndrop policy if exists \"men change their own data\" on public.user_data;\ncreate policy \"men change their own data\" on public.user_data\n  for update using (user_id = auth.uid()) with check (user_id = auth.uid());\n\ndrop policy if exists \"men delete their own data\" on public.user_data;\ncreate policy \"men delete their own data\" on public.user_data\n  for delete using (user_id = auth.uid());\n\ncreate or replace function public.user_data_touch()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  new.updated_at := now();\n  return new;\nend;\n$$;\n\ndrop trigger if exists user_data_touch on public.user_data;\ncreate trigger user_data_touch\n  before insert or update on public.user_data\n  for each row execute function public.user_data_touch();\n\n-- ─────────────────────────────────────────────\n-- 2. \"Delete my account\": removes his login and (through cascade) all his data\n-- ─────────────────────────────────────────────\ncreate or replace function public.delete_my_account()\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.uid() is null then\n    raise exception 'not signed in';\n  end if;\n  delete from public.user_data where user_id = auth.uid();\n  delete from auth.users where id = auth.uid();\nend;\n$$;\n\nrevoke all on function public.delete_my_account() from public;\ngrant execute on function public.delete_my_account() to authenticated;\n",
  "public/manifest.webmanifest": "{\n  \"name\": \"Kayani Men's Social\",\n  \"short_name\": \"Men's Social\",\n  \"description\": \"Your private companion for men's wellness.\",\n  \"start_url\": \"/social\",\n  \"display\": \"standalone\",\n  \"background_color\": \"#f4f6f4\",\n  \"theme_color\": \"#0f5c46\",\n  \"icons\": [{ \"src\": \"/favicon.ico\", \"sizes\": \"48x48\", \"type\": \"image/x-icon\" }]\n}\n",
  "src/app/(app)/layout.tsx": "import BottomNav from \"@/components/BottomNav\";\nimport { ToastProvider } from \"@/components/motion/Toast\";\nimport AccountSync from \"@/components/account/AccountSync\";\nimport TabSwipe from \"@/components/TabSwipe\";\nimport AccountInviteSheet from \"@/components/account/AccountInvite\";\n\nexport default function AppLayout({ children }: { children: React.ReactNode }) {\n  return (\n    <ToastProvider>\n      <AccountSync />\n      <TabSwipe />\n      <AccountInviteSheet />\n      <main className=\"mx-auto min-h-dvh max-w-md px-5 pb-28 pt-6\">{children}</main>\n      <BottomNav />\n    </ToastProvider>\n  );\n}\n",
  "src/app/(app)/man/page.tsx": "\"use client\";\n\n// \"Man\": Home and Progress in one place.\n// Top: what to do today (all interactive right here). Bottom: his trends.\n\nimport TopBar from \"@/components/feed/TopBar\";\nimport ActivitiesCard from \"@/components/feed/ActivitiesCard\";\nimport TrendsSection from \"@/components/feed/TrendsSection\";\nimport { EndCard, LessonCard, ReminderCard, TipCard, TodayCard } from \"@/components/feed/FeedCards\";\nimport { useHomeFeed } from \"@/components/feed/useHomeFeed\";\nimport CheckInCard from \"@/components/progress/CheckInCard\";\nimport HydrationCard from \"@/components/progress/HydrationCard\";\nimport SleepCard from \"@/components/progress/SleepCard\";\nimport SaveProgressCard, { WhereSavedNote } from \"@/components/account/SaveProgressCard\";\n\nexport default function ManPage() {\n  const f = useHomeFeed();\n\n  if (!f.ready) {\n    return (\n      <div className=\"space-y-4\">\n        <TopBar />\n        <div className=\"h-40 animate-pulse rounded-3xl bg-forest-deep/20\" />\n        <div className=\"h-64 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"stagger space-y-4\">\n      <TopBar />\n      <TodayCard f={f} />\n      {f.allClosed ? <EndCard /> : <ReminderCard f={f} />}\n\n      <div id=\"checkin\" className=\"scroll-mt-4\">\n        <CheckInCard period={1} />\n      </div>\n      <div id=\"sleep\" className=\"scroll-mt-4\">\n        <SleepCard period={1} />\n      </div>\n      <div id=\"water\" className=\"scroll-mt-4\">\n        <HydrationCard period={1} />\n      </div>\n      <ActivitiesCard f={f} />\n      <SaveProgressCard points={f.points} />\n\n      <LessonCard f={f} />\n      <TipCard f={f} />\n\n      <div className=\"pt-4\">\n        <TrendsSection />\n      </div>\n\n      <WhereSavedNote />\n    </div>\n  );\n}\n",
  "src/app/(app)/me/page.tsx": "\"use client\";\n\n// \"Me\": who he is in the app, what he's earned, his goals, settings and privacy controls.\n// Everything here comes from his real activity on this phone.\n\nimport ProfileHero from \"@/components/me/ProfileHero\";\nimport BadgesSection from \"@/components/me/BadgesSection\";\nimport { GoalsCard, PrivacyCard, SettingsCard } from \"@/components/me/SettingsSections\";\nimport { useHomeFeed } from \"@/components/feed/useHomeFeed\";\nimport { useFeed } from \"@/lib/feed/store\";\nimport { computeBadges, firstActiveDay } from \"@/lib/me/badges\";\nimport { useLang } from \"@/lib/me/lang\";\nimport { goalFor, useProgress } from \"@/lib/progress/store\";\nimport { useSocial } from \"@/lib/social/store\";\nimport { useAccount } from \"@/lib/account/useAccount\";\n\nexport default function MePage() {\n  const f = useHomeFeed();\n  const feed = useFeed();\n  const progress = useProgress();\n  const social = useSocial();\n  const lang = useLang();\n  const acc = useAccount();\n\n  if (!f.ready || !social.ready) {\n    return (\n      <div className=\"space-y-4\" aria-busy=\"true\" aria-label=\"Loading\">\n        <div className=\"h-52 animate-pulse rounded-[28px] bg-forest-deep/15\" />\n        <div className=\"h-64 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n      </div>\n    );\n  }\n\n  const badges = computeBadges({\n    records: progress.records,\n    goals: progress.goals,\n    feed,\n    points: f.points,\n    pointDays: f.pointDays,\n    bookmarks: Object.keys(social.bookmarks).length,\n    posts: social.posts.length,\n    replies: social.replies.length,\n  });\n\n  return (\n    <div className=\"stagger space-y-4\">\n      <h1 className=\"text-2xl font-bold\">Me</h1>\n      <ProfileHero\n        nickname={social.nickname}\n        points={f.points}\n        level={f.level}\n        streak={f.streak}\n        since={firstActiveDay({ records: progress.records, feed })}\n      />\n      <BadgesSection badges={badges} />\n      <GoalsCard\n        water={goalFor(progress.goals, \"water\")?.target ?? null}\n        sleep={goalFor(progress.goals, \"sleep\")?.target ?? null}\n        interests={social.interests}\n      />\n      <SettingsCard lang={lang} discreet={feed.settings.discreet} />\n      <PrivacyCard acc={acc} />\n      <p className=\"pb-2 text-center text-[11px] text-ink-soft\">Kayani Men&apos;s Social · test version</p>\n    </div>\n  );\n}\n",
  "src/app/(app)/template.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport { slideDirection } from \"@/lib/tabs\";\n\n// A \"template\" re-runs on every page change. Switching tabs slides the new page in from the side\n// you're heading to (like an iPhone app); other page changes fade in.\nexport default function Template({ children }: { children: React.ReactNode }) {\n  const [dir] = useState(() => slideDirection.take());\n  const cls = dir === \"left\" ? \"slide-from-right\" : dir === \"right\" ? \"slide-from-left\" : \"page-enter\";\n  return (\n    <div id=\"tab-page\" className={cls}>\n      {children}\n    </div>\n  );\n}\n",
  "src/app/globals.css": "@import \"tailwindcss\";\n\n/* Brand tokens — Kayani Men's Social (Fernly-inspired: white, forest green, mint) */\n:root {\n  --bg: #f4f6f4;\n  --surface: #ffffff;\n  --ink: #0f1f1a;\n  --ink-soft: #5b6b65;\n  --line: #e3e8e5;\n  --forest: #0f5c46;\n  --forest-deep: #073b2d;\n  --mint: #dff3ea;\n  --mint-strong: #5dcaa5;\n}\n\n@theme inline {\n  --color-bg: var(--bg);\n  --color-surface: var(--surface);\n  --color-ink: var(--ink);\n  --color-ink-soft: var(--ink-soft);\n  --color-line: var(--line);\n  --color-forest: var(--forest);\n  --color-forest-deep: var(--forest-deep);\n  --color-mint: var(--mint);\n  --color-mint-strong: var(--mint-strong);\n  --font-sans: \"Plus Jakarta Sans Variable\", system-ui, sans-serif;\n}\n\nhtml {\n  scroll-behavior: smooth;\n}\n\nbody {\n  background: var(--bg);\n  color: var(--ink);\n  font-family: \"Plus Jakarta Sans Variable\", system-ui, sans-serif;\n  -webkit-tap-highlight-color: transparent;\n}\n\n/* Gentle entrance motion */\n@keyframes rise {\n  from { opacity: 0; transform: translateY(12px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n.rise { animation: rise 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n.rise-2 { animation-delay: 0.08s; }\n.rise-3 { animation-delay: 0.16s; }\n.rise-4 { animation-delay: 0.24s; }\n\n/* ===== Motion kit (Fernly-style) ===== */\n\n/* 1. Page enter: whole page fades in */\n@keyframes page-in {\n  from { opacity: 0; }\n  to { opacity: 1; }\n}\n.page-enter { animation: page-in 0.35s ease-out both; }\n\n/* 1b. Stagger: each direct child rises in, one after another */\n.stagger > * { animation: rise 0.55s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n.stagger > *:nth-child(1) { animation-delay: 0.04s; }\n.stagger > *:nth-child(2) { animation-delay: 0.10s; }\n.stagger > *:nth-child(3) { animation-delay: 0.16s; }\n.stagger > *:nth-child(4) { animation-delay: 0.22s; }\n.stagger > *:nth-child(5) { animation-delay: 0.28s; }\n.stagger > *:nth-child(6) { animation-delay: 0.34s; }\n.stagger > *:nth-child(7) { animation-delay: 0.40s; }\n.stagger > *:nth-child(n + 8) { animation-delay: 0.46s; }\n\n/* 2. Bars grow upward */\n@keyframes grow-up {\n  from { transform: scaleY(0); }\n  to { transform: scaleY(1); }\n}\n.grow-bar {\n  transform-origin: bottom;\n  animation: grow-up 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) both;\n}\n\n/* 3. Toast pill: pops up from the bottom, then fades away */\n@keyframes toast-in {\n  from { opacity: 0; transform: translate(-50%, 16px) scale(0.96); }\n  to { opacity: 1; transform: translate(-50%, 0) scale(1); }\n}\n@keyframes toast-out {\n  from { opacity: 1; transform: translate(-50%, 0) scale(1); }\n  to { opacity: 0; transform: translate(-50%, 8px) scale(0.98); }\n}\n.toast-in { animation: toast-in 0.32s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n.toast-out { animation: toast-out 0.25s ease-in both; }\n\n/* 4. Popup sheet: background dims + blurs, card scales in */\n@keyframes backdrop-in {\n  from { opacity: 0; }\n  to { opacity: 1; }\n}\n@keyframes sheet-in {\n  from { opacity: 0; transform: translateY(16px) scale(0.97); }\n  to { opacity: 1; transform: translateY(0) scale(1); }\n}\n.backdrop-in { animation: backdrop-in 0.25s ease-out both; }\n.sheet-in { animation: sheet-in 0.35s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n\n/* 5. Points burst: \"+15\" floats up and fades when an activity is done */\n@keyframes float-up {\n  0% { opacity: 0; transform: translateY(4px) scale(0.9); }\n  20% { opacity: 1; transform: translateY(0) scale(1.05); }\n  100% { opacity: 0; transform: translateY(-28px) scale(1); }\n}\n.float-up { animation: float-up 0.9s ease-out both; pointer-events: none; }\n\n/* Hatched (striped) bar, like Fernly's empty days */\n.hatch {\n  background-image: repeating-linear-gradient(\n    -45deg,\n    var(--line) 0 2px,\n    transparent 2px 7px\n  );\n  box-shadow: inset 0 0 0 1px var(--line);\n}\n\n/* Respect phones set to \"reduce motion\" */\n@media (prefers-reduced-motion: reduce) {\n  .rise, .page-enter, .stagger > *, .grow-bar,\n  .toast-in, .toast-out, .backdrop-in, .sheet-in, .float-up { animation: none; }\n}\n\n/* ===== Tabs: slide between tabs + liquid glass tab bar ===== */\n@keyframes slide-from-right {\n  from { opacity: 0; transform: translateX(28%); }\n  to { opacity: 1; transform: translateX(0); }\n}\n@keyframes slide-from-left {\n  from { opacity: 0; transform: translateX(-28%); }\n  to { opacity: 1; transform: translateX(0); }\n}\n.slide-from-right { animation: slide-from-right 0.38s cubic-bezier(0.2, 0.8, 0.2, 1) backwards; }\n.slide-from-left { animation: slide-from-left 0.38s cubic-bezier(0.2, 0.8, 0.2, 1) backwards; }\n\n/* Frosted glass bar: page shows through, blurred and a little brighter */\n.glass-bar {\n  background: linear-gradient(180deg, rgba(255, 255, 255, 0.62), rgba(255, 255, 255, 0.42));\n  -webkit-backdrop-filter: blur(22px) saturate(1.8);\n  backdrop-filter: blur(22px) saturate(1.8);\n  border: 1px solid rgba(255, 255, 255, 0.7);\n  box-shadow:\n    0 10px 30px rgba(7, 59, 45, 0.16),\n    0 2px 6px rgba(7, 59, 45, 0.06),\n    inset 0 1px 0 rgba(255, 255, 255, 0.9),\n    inset 0 -1px 0 rgba(7, 59, 45, 0.04);\n}\n/* The bubble: a brighter piece of glass with a mint tint and a light edge */\n.glass-bubble {\n  background: linear-gradient(180deg, rgba(255, 255, 255, 0.95), rgba(223, 243, 234, 0.85));\n  box-shadow:\n    0 4px 14px rgba(15, 92, 70, 0.18),\n    inset 0 1px 0 rgba(255, 255, 255, 1),\n    inset 0 0 0 1px rgba(93, 202, 165, 0.25);\n}\n/* Bubble position = active tab, plus how far the finger has dragged */\n.tab-bubble-track {\n  transform: translateX(calc((var(--tab-index, 0) + var(--tab-drag, 0)) * 100%));\n  transition: transform 0.5s cubic-bezier(0.34, 1.4, 0.64, 1);\n}\n.tab-swiping .tab-bubble-track { transition: none; }\n/* A little \"liquid\" stretch when it arrives on a new tab */\n@keyframes liquid-pop {\n  0% { transform: scale(0.86, 0.92); }\n  45% { transform: scale(1.12, 0.94); }\n  70% { transform: scale(0.97, 1.03); }\n  100% { transform: scale(1, 1); }\n}\n.liquid-pop { animation: liquid-pop 0.55s cubic-bezier(0.3, 1.2, 0.5, 1) both; }\n@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {\n  .glass-bar { background: rgba(255, 255, 255, 0.96); }\n}\n@media (prefers-reduced-motion: reduce) {\n  .slide-from-right, .slide-from-left, .liquid-pop { animation: none; }\n  .tab-bubble-track { transition: none; }\n}\n",
  "src/app/page.tsx": "\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport { useRouter } from \"next/navigation\";\nimport { account, accountLabel, useAccount } from \"@/lib/account/useAccount\";\nimport { stopSync } from \"@/lib/account/sync\";\n\ntype Lang = \"en\" | \"sw\";\n\nconst copy = {\n  en: {\n    tagline: \"Your private companion for men's wellness\",\n    points: [\n      \"Daily activities that fit your life\",\n      \"Short lessons from trusted sources\",\n      \"A private space to track how you feel\",\n    ],\n    ageQuestion: \"This app talks openly about men's sexual health. By continuing you confirm you are 18 or older.\",\n    start: \"Get started\",\n    create: \"Create free account\",\n    login: \"I have an account · Log in\",\n    continue: \"Continue\",\n    signedInAs: \"Signed in as\",\n    notYou: \"Not you?\",\n    privacy: \"No sign-up needed to look around. Your data stays private.\",\n  },\n  sw: {\n    tagline: \"Mwenzako wa siri kwa afya ya mwanaume\",\n    points: [\n      \"Shughuli za kila siku zinazoendana na maisha yako\",\n      \"Masomo mafupi kutoka vyanzo vya kuaminika\",\n      \"Sehemu ya siri ya kufuatilia unavyojisikia\",\n    ],\n    ageQuestion: \"Programu hii inazungumzia afya ya uzazi ya mwanaume kwa uwazi. Kwa kuendelea unathibitisha una miaka 18 au zaidi.\",\n    start: \"Anza sasa\",\n    create: \"Fungua akaunti bure\",\n    login: \"Nina akaunti · Ingia\",\n    continue: \"Endelea\",\n    signedInAs: \"Umeingia kama\",\n    notYou: \"Si wewe?\",\n    privacy: \"Huhitaji kujisajili ili kuangalia. Taarifa zako ni siri.\",\n  },\n} as const;\n\nexport default function Welcome() {\n  const router = useRouter();\n  const [lang, setLang] = useState<Lang>(\"en\");\n  const t = copy[lang];\n\n  // This page always stays here (no automatic redirect). If he's already signed in,\n  // the buttons change to \"Continue\" so he isn't asked to log in again.\n  const acc = useAccount();\n\n  // Remember the language he picked last time\n  useEffect(() => {\n    try {\n      if (localStorage.getItem(\"ms_lang\") === \"sw\") setLang(\"sw\");\n    } catch {}\n  }, []);\n\n  /** Every choice confirms 18+ and saves the language, then goes in as a guest or to the account screen. */\n  function enter(to: string) {\n    try {\n      localStorage.setItem(\"ms_age_ok\", \"1\");\n      localStorage.setItem(\"ms_lang\", lang);\n    } catch {}\n    router.push(to);\n  }\n\n  return (\n    <main className=\"mx-auto flex min-h-dvh max-w-md flex-col px-5 pb-8 pt-6\">\n      {/* Top bar: logo + language switch */}\n      <header className=\"rise flex items-center justify-between\">\n        <div className=\"flex items-center gap-2\">\n          <div className=\"flex h-9 w-9 items-center justify-center rounded-xl bg-forest text-sm font-bold text-mint\">\n            MS\n          </div>\n          <span className=\"text-base font-semibold\">Men&apos;s Social</span>\n        </div>\n        <div className=\"flex rounded-full bg-surface p-1 text-xs font-semibold ring-1 ring-line\">\n          {([\"en\", \"sw\"] as const).map((l) => (\n            <button\n              key={l}\n              onClick={() => setLang(l)}\n              className={`rounded-full px-3 py-1.5 transition-colors ${\n                lang === l ? \"bg-forest text-white\" : \"text-ink-soft\"\n              }`}\n              aria-pressed={lang === l}\n            >\n              {l.toUpperCase()}\n            </button>\n          ))}\n        </div>\n      </header>\n\n      {/* Hero card */}\n      <section className=\"rise rise-2 mt-8 rounded-3xl bg-forest-deep p-6 text-white\">\n        <p className=\"text-sm text-mint-strong\">Kayani Men&apos;s Social</p>\n        <h1 className=\"mt-2 text-[28px] font-bold leading-tight\">{t.tagline}</h1>\n        <ul className=\"mt-6 space-y-3\">\n          {t.points.map((p) => (\n            <li key={p} className=\"flex items-start gap-3 text-sm text-mint\">\n              <span className=\"mt-1.5 h-2 w-2 shrink-0 rounded-full bg-mint-strong\" />\n              {p}\n            </li>\n          ))}\n        </ul>\n      </section>\n\n      {/* Age check + three ways in */}\n      <section className=\"rise rise-3 mt-4 rounded-3xl bg-surface p-5 ring-1 ring-line\">\n        <p className=\"text-sm text-ink-soft\">{t.ageQuestion}</p>\n        {acc.status === \"signedIn\" ? (\n          <>\n            <button\n              onClick={() => enter(\"/social\")}\n              className=\"mt-4 w-full rounded-full bg-forest py-3.5 text-sm font-semibold text-white transition-transform active:scale-[0.98]\"\n            >\n              {t.continue}\n            </button>\n            <p className=\"mt-3 text-center text-xs text-ink-soft\">\n              {t.signedInAs} {accountLabel(acc.user)} ·{\" \"}\n              <button\n                onClick={async () => {\n                  // Another man on this phone: remove the signed-in man's data from it, then sign out\n                  stopSync({ clearPhone: true });\n                  await account.signOut();\n                }}\n                className=\"font-semibold text-forest\"\n              >\n                {t.notYou}\n              </button>\n            </p>\n          </>\n        ) : (\n          <>\n            <button\n              onClick={() => enter(\"/social\")}\n              className=\"mt-4 w-full rounded-full bg-forest py-3.5 text-sm font-semibold text-white transition-transform active:scale-[0.98]\"\n            >\n              {t.start}\n            </button>\n            <button\n              onClick={() => enter(\"/account?next=/social\")}\n              className=\"mt-2 w-full rounded-full bg-mint py-3.5 text-sm font-semibold text-forest-deep transition-transform active:scale-[0.98]\"\n            >\n              {t.create}\n            </button>\n            <button\n              onClick={() => enter(\"/account?mode=login&next=/social\")}\n              className=\"mt-2 w-full py-2.5 text-sm font-semibold text-forest\"\n            >\n              {t.login}\n            </button>\n          </>\n        )}\n      </section>\n\n      <p className=\"rise rise-4 mt-auto pt-8 text-center text-xs text-ink-soft\">{t.privacy}</p>\n    </main>\n  );\n}\n",
  "src/components/BottomNav.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { usePathname } from \"next/navigation\";\nimport { MessageCircle, Sparkles, UserRound } from \"lucide-react\";\nimport { slideDirection, TAB_PATHS, tabFor } from \"@/lib/tabs\";\n\n// Three tabs only. \"Man\" is Home and Progress in one place.\nconst tabs = [\n  { href: TAB_PATHS[0], label: \"Social\", Icon: MessageCircle },\n  { href: TAB_PATHS[1], label: \"Man\", Icon: Sparkles },\n  { href: TAB_PATHS[2], label: \"Me\", Icon: UserRound },\n];\n\n/** Floating \"liquid glass\" tab bar: the page shows through, blurred. A glass bubble slides to the active tab. */\nexport default function BottomNav() {\n  const pathname = usePathname();\n  const active = tabFor(pathname);\n\n  return (\n    <nav\n      aria-label=\"Main\"\n      className=\"fixed inset-x-0 bottom-0 z-20 px-4 pb-[max(12px,env(safe-area-inset-bottom))]\"\n    >\n      <div className=\"glass-bar relative mx-auto max-w-sm rounded-[30px] p-1.5\">\n        {/* The sliding glass bubble behind the active tab (follows the finger while swiping) */}\n        {active >= 0 && (\n          <div\n            aria-hidden\n            className=\"tab-bubble-track pointer-events-none absolute inset-y-1.5 left-1.5 w-[calc((100%-12px)/3)]\"\n            style={{ [\"--tab-index\" as string]: active }}\n          >\n            <div key={active} className=\"glass-bubble liquid-pop h-full w-full rounded-[24px]\" />\n          </div>\n        )}\n        <ul className=\"relative grid grid-cols-3\">\n          {tabs.map(({ href, label, Icon }, i) => {\n            const on = i === active;\n            return (\n              <li key={href}>\n                <Link\n                  href={href}\n                  aria-current={on ? \"page\" : undefined}\n                  onClick={() => active >= 0 && i !== active && slideDirection.set(i > active ? \"left\" : \"right\")}\n                  className={`flex flex-col items-center gap-0.5 rounded-[24px] py-2 text-[11px] font-semibold transition-colors duration-300 ${\n                    on ? \"text-forest-deep\" : \"text-ink-soft\"\n                  }`}\n                >\n                  <Icon size={21} strokeWidth={on ? 2.4 : 1.8} className={`transition-transform duration-300 ${on ? \"scale-110\" : \"\"}`} />\n                  {label}\n                </Link>\n              </li>\n            );\n          })}\n        </ul>\n      </div>\n    </nav>\n  );\n}\n",
  "src/components/me/SettingsSections.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport { ChevronRight, Download, Droplet, EyeOff, Globe, Moon, ShieldCheck, Stethoscope, Trash2 } from \"lucide-react\";\nimport Sheet from \"@/components/motion/Sheet\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport InterestsSheet from \"@/components/social/InterestsSheet\";\nimport { TOPICS } from \"@/lib/content/library\";\nimport type { TopicId } from \"@/lib/content/types\";\nimport { feedStore } from \"@/lib/feed/store\";\nimport { deleteMyData, exportMyData } from \"@/lib/me/data\";\nimport { setLang, type Lang } from \"@/lib/me/lang\";\nimport { progressStore } from \"@/lib/progress/store\";\nimport AccountCard from \"@/components/account/AccountCard\";\nimport type { AccountState } from \"@/lib/account/useAccount\";\nimport { deleteCloudData, stopSync } from \"@/lib/account/sync\";\n\n/* ───────── Goals and topics ───────── */\nexport function GoalsCard({ water, sleep, interests }: { water: number | null; sleep: number | null; interests: TopicId[] }) {\n  const showToast = useToast();\n  const [edit, setEdit] = useState<\"water\" | \"sleep\" | null>(null);\n  const [value, setValue] = useState(0);\n  const [topics, setTopics] = useState(false);\n\n  const open = (m: \"water\" | \"sleep\") => {\n    setValue(m === \"water\" ? (water ?? 2500) : (sleep ?? 420));\n    setEdit(m);\n  };\n  const step = edit === \"water\" ? 250 : 30;\n  const [min, max] = edit === \"water\" ? [500, 5000] : [240, 720];\n  const fmt = (m: \"water\" | \"sleep\", v: number) => (m === \"water\" ? `${(v / 1000).toFixed(v % 1000 ? 2 : 1).replace(/0$/, \"\")} L` : `${Math.floor(v / 60)}h${v % 60 ? ` ${v % 60}m` : \"\"}`);\n\n  function save() {\n    if (!edit) return;\n    progressStore.setGoal(edit, value, edit === \"water\" ? \"ml\" : \"min\");\n    showToast(`${edit === \"water\" ? \"Water\" : \"Sleep\"} goal: ${fmt(edit, value)}`);\n    setEdit(null);\n  }\n\n  return (\n    <section className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n      <h2 className=\"text-lg font-bold\">My goals</h2>\n      <div className=\"mt-3 grid grid-cols-2 gap-3\">\n        <button onClick={() => open(\"water\")} className=\"rounded-2xl bg-bg p-4 text-left ring-1 ring-line\">\n          <Droplet size={18} className=\"text-forest\" />\n          <p className=\"mt-2 text-xl font-bold\">{water ? fmt(\"water\", water) : \"Not set\"}</p>\n          <p className=\"text-xs text-ink-soft\">water a day</p>\n        </button>\n        <button onClick={() => open(\"sleep\")} className=\"rounded-2xl bg-bg p-4 text-left ring-1 ring-line\">\n          <Moon size={18} className=\"text-forest\" />\n          <p className=\"mt-2 text-xl font-bold\">{sleep ? fmt(\"sleep\", sleep) : \"Not set\"}</p>\n          <p className=\"text-xs text-ink-soft\">sleep a night</p>\n        </button>\n      </div>\n\n      <button onClick={() => setTopics(true)} className=\"mt-3 flex w-full items-center justify-between rounded-2xl bg-mint/60 px-4 py-3 text-left\">\n        <span className=\"min-w-0\">\n          <span className=\"block text-sm font-semibold text-forest-deep\">Topics I follow</span>\n          <span className=\"block truncate text-xs text-forest\">\n            {interests.length ? TOPICS.filter((t) => interests.includes(t.id)).map((t) => t.short).join(\" · \") : \"None yet. Choose what matters to you.\"}\n          </span>\n        </span>\n        <ChevronRight size={18} className=\"shrink-0 text-forest\" />\n      </button>\n\n      <Sheet open={edit !== null} onClose={() => setEdit(null)} title={edit === \"water\" ? \"Daily water goal\" : \"Nightly sleep goal\"}>\n        {edit && (\n          <>\n            <div className=\"flex items-center justify-between gap-3\">\n              <button aria-label=\"Less\" onClick={() => setValue((v) => Math.max(min, v - step))} className=\"h-12 w-12 rounded-full bg-bg text-2xl font-bold ring-1 ring-line\">\n                −\n              </button>\n              <p className=\"text-3xl font-bold\" aria-live=\"polite\">\n                {fmt(edit, value)}\n              </p>\n              <button aria-label=\"More\" onClick={() => setValue((v) => Math.min(max, v + step))} className=\"h-12 w-12 rounded-full bg-bg text-2xl font-bold ring-1 ring-line\">\n                +\n              </button>\n            </div>\n            <p className=\"mt-3 text-xs text-ink-soft\">\n              {edit === \"water\"\n                ? \"Most men do well with about 2 to 3 litres a day, more in heat or after exercise.\"\n                : \"Most adults need 7 to 9 hours. Pick a goal you can really keep.\"}\n            </p>\n            <button onClick={save} className=\"mt-4 w-full rounded-full bg-forest py-3 text-sm font-semibold text-white\">\n              Save goal\n            </button>\n          </>\n        )}\n      </Sheet>\n      <InterestsSheet open={topics} onClose={() => setTopics(false)} current={interests} />\n    </section>\n  );\n}\n\n/* ───────── App settings ───────── */\nexport function SettingsCard({ lang, discreet }: { lang: Lang; discreet: boolean }) {\n  const showToast = useToast();\n  return (\n    <section className=\"divide-y divide-line rounded-3xl bg-surface ring-1 ring-line\">\n      <div className=\"flex items-center gap-3 p-5\">\n        <Globe size={18} className=\"shrink-0 text-forest\" />\n        <div className=\"min-w-0 flex-1\">\n          <p className=\"font-semibold\">Language</p>\n          <p className=\"text-xs text-ink-soft\">Guides open in this language when there&apos;s a Kiswahili version.</p>\n        </div>\n        <div className=\"inline-flex shrink-0 rounded-full bg-bg p-1 text-xs font-semibold ring-1 ring-line\" role=\"radiogroup\" aria-label=\"Language\">\n          {([\"en\", \"sw\"] as const).map((l) => (\n            <button\n              key={l}\n              role=\"radio\"\n              aria-checked={lang === l}\n              onClick={() => {\n                setLang(l);\n                showToast(l === \"sw\" ? \"Kiswahili imechaguliwa\" : \"English selected\");\n              }}\n              className={`rounded-full px-3 py-1.5 ${lang === l ? \"bg-forest text-white\" : \"text-ink-soft\"}`}\n            >\n              {l === \"en\" ? \"EN\" : \"SW\"}\n            </button>\n          ))}\n        </div>\n      </div>\n\n      <label className=\"flex cursor-pointer items-center gap-3 p-5\">\n        <EyeOff size={18} className=\"shrink-0 text-forest\" />\n        <span className=\"min-w-0 flex-1\">\n          <span className=\"block font-semibold\">Discreet mode</span>\n          <span className=\"block text-xs text-ink-soft\">\n            Uses neutral wording on the Man tab, so private topics don&apos;t show if someone looks at your screen.\n          </span>\n        </span>\n        <input\n          type=\"checkbox\"\n          role=\"switch\"\n          checked={discreet}\n          onChange={(e) => {\n            feedStore.setDiscreet(e.target.checked);\n            showToast(e.target.checked ? \"Discreet mode on\" : \"Discreet mode off\");\n          }}\n          className=\"peer sr-only\"\n        />\n        <span\n          aria-hidden\n          className=\"relative h-7 w-12 shrink-0 rounded-full bg-line transition-colors peer-checked:bg-forest peer-focus-visible:ring-2 peer-focus-visible:ring-forest after:absolute after:left-1 after:top-1 after:h-5 after:w-5 after:rounded-full after:bg-white after:shadow after:transition-transform peer-checked:after:translate-x-5\"\n        />\n      </label>\n    </section>\n  );\n}\n\n/* ───────── Account, privacy and help ───────── */\nexport function PrivacyCard({ acc }: { acc: AccountState }) {\n  const signedIn = acc.status === \"signedIn\";\n  const showToast = useToast();\n  const [confirm, setConfirm] = useState(false);\n\n  function download() {\n    try {\n      const data = exportMyData(localStorage);\n      const blob = new Blob([JSON.stringify(data, null, 2)], { type: \"application/json\" });\n      const url = URL.createObjectURL(blob);\n      const a = document.createElement(\"a\");\n      a.href = url;\n      a.download = `mens-social-my-data-${new Date().toISOString().slice(0, 10)}.json`;\n      a.click();\n      setTimeout(() => URL.revokeObjectURL(url), 1000);\n      showToast(\"Your data is downloading\");\n    } catch {\n      showToast(\"Couldn't download on this browser\");\n    }\n  }\n\n  async function removeAll() {\n    if (signedIn) {\n      stopSync({ clearPhone: false });\n      try {\n        await deleteCloudData(acc.user.id);\n      } catch {\n        showToast(\"Couldn't delete from your account. Check your internet.\");\n        return;\n      }\n    }\n    try {\n      deleteMyData(localStorage);\n    } catch {}\n    // Reload so every screen starts fresh\n    window.location.href = \"/\";\n  }\n\n  return (\n    <>\n      <AccountCard acc={acc} />\n\n      <section className=\"divide-y divide-line rounded-3xl bg-surface ring-1 ring-line\">\n        <div className=\"flex gap-3 p-5\">\n          <ShieldCheck size={18} className=\"mt-0.5 shrink-0 text-forest\" />\n          <div>\n            <p className=\"font-semibold\">Your privacy</p>\n            <p className=\"mt-1 text-sm text-ink-soft\">\n              {signedIn\n                ? \"Your check-ins, sleep, water and notes are saved privately in your account. Only you can see them, not even Kayani staff.\"\n                : \"Your check-ins, sleep, water and notes stay on this phone.\"}{\" \"}\n              We never use them for adverts and never ask for intimate photos.\n            </p>\n          </div>\n        </div>\n        <button onClick={download} className=\"flex w-full items-center gap-3 p-5 text-left\">\n          <Download size={18} className=\"shrink-0 text-forest\" />\n          <span className=\"flex-1 font-semibold\">Download my data</span>\n          <ChevronRight size={16} className=\"text-ink-soft\" />\n        </button>\n        <button onClick={() => setConfirm(true)} className=\"flex w-full items-center gap-3 p-5 text-left text-red-700\">\n          <Trash2 size={18} className=\"shrink-0\" />\n          <span className=\"flex-1 font-semibold\">Delete all my data</span>\n          <ChevronRight size={16} />\n        </button>\n      </section>\n\n      <section className=\"divide-y divide-line rounded-3xl bg-surface ring-1 ring-line\">\n        <Link href=\"/social/c/tool-doctor-check\" className=\"flex items-center gap-3 p-5\">\n          <Stethoscope size={18} className=\"shrink-0 text-forest\" />\n          <span className=\"flex-1\">\n            <span className=\"block font-semibold\">Should I see a doctor?</span>\n            <span className=\"block text-xs text-ink-soft\">A quick check of signs that need a professional.</span>\n          </span>\n          <ChevronRight size={16} className=\"text-ink-soft\" />\n        </Link>\n        <p className=\"p-5 text-xs leading-relaxed text-ink-soft\">\n          Men&apos;s Social gives general education, not medical advice. It doesn&apos;t diagnose or treat any condition. If\n          something worries you, or symptoms last or get worse, please see a qualified health professional.\n        </p>\n      </section>\n\n      <Sheet open={confirm} onClose={() => setConfirm(false)} title=\"Delete everything?\">\n        <p className=\"text-sm text-ink-soft\">\n          This removes your points, badges, check-ins, sleep and water records, saved guides and posts\n          {signedIn ? \" from this phone and from your account (your login stays)\" : \" from this phone\"}. It can&apos;t be undone.\n        </p>\n        <div className=\"mt-4 grid grid-cols-2 gap-2\">\n          <button onClick={() => setConfirm(false)} className=\"rounded-full py-3 text-sm font-semibold ring-1 ring-line\">\n            Keep my data\n          </button>\n          <button onClick={removeAll} className=\"rounded-full bg-red-700 py-3 text-sm font-semibold text-white\">\n            Delete\n          </button>\n        </div>\n      </Sheet>\n    </>\n  );\n}\n",
  "src/components/social/BookmarkButton.tsx": "\"use client\";\n\nimport { Bookmark } from \"lucide-react\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { socialStore, useSocial } from \"@/lib/social/store\";\nimport { inviteToAccount } from \"@/components/account/AccountInvite\";\n\nexport default function BookmarkButton({\n  contentId,\n  variant = \"light\",\n  size = 18,\n}: {\n  contentId: string;\n  variant?: \"light\" | \"dark\" | \"plain\";\n  size?: number;\n}) {\n  const { bookmarks, ready } = useSocial();\n  const showToast = useToast();\n  const saved = Boolean(bookmarks[contentId]);\n\n  const styles = {\n    light: \"bg-surface text-ink ring-1 ring-line\",\n    dark: \"bg-white/15 text-white\",\n    plain: \"text-ink-soft\",\n  }[variant];\n\n  return (\n    <button\n      type=\"button\"\n      disabled={!ready}\n      aria-pressed={saved}\n      aria-label={saved ? \"Remove from saved\" : \"Save for later\"}\n      onClick={(e) => {\n        e.preventDefault();\n        e.stopPropagation();\n        const nowSaved = socialStore.toggleBookmark(contentId);\n        showToast(nowSaved ? \"Saved\" : \"Removed from saved\");\n        if (nowSaved) inviteToAccount(\"first-save\");\n      }}\n      className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-full transition-transform active:scale-90 ${styles}`}\n    >\n      <Bookmark size={size} fill={saved ? \"currentColor\" : \"none\"} strokeWidth={2} />\n    </button>\n  );\n}\n",
  "src/lib/feed/store.ts": "\"use client\";\n\n// Saves what he did with each activity (Done / Later / Skip) and which lessons he read.\n// NOW: on the phone. LATER: Supabase (same shape).\n\nimport { useSyncExternalStore } from \"react\";\nimport { dateKey } from \"../progress/dates\";\n\nexport type ChoiceStatus = \"done\" | \"later\" | \"skipped\";\n\nexport interface FeedDB {\n  /** days[\"2026-10-13\"][\"walk\"] = { status: \"done\", at: \"...\" } */\n  days: Record<string, Record<string, { status: ChoiceStatus; at: string }>>;\n  /** lessons[\"sleep-and-energy\"] = { localDate, at } */\n  lessons: Record<string, { localDate: string; at: string }>;\n  settings: { discreet: boolean };\n}\nexport type FeedState = FeedDB & { ready: boolean };\n\nconst KEY = \"ms_feed_v1\";\nconst EMPTY: FeedDB = { days: {}, lessons: {}, settings: { discreet: false } };\nconst SERVER_STATE: FeedState = { ...EMPTY, ready: false };\nlet cache: FeedState | null = null;\nconst listeners = new Set<() => void>();\n/** Told only about HIS changes (not about data arriving from his account), so they can be saved to it. */\nconst changeListeners = new Set<() => void>();\n\nfunction load(): FeedState {\n  if (cache) return cache;\n  let db: FeedDB = EMPTY;\n  try {\n    const raw = localStorage.getItem(KEY);\n    if (raw) {\n      const p = JSON.parse(raw) as Partial<FeedDB>;\n      db = {\n        days: p.days && typeof p.days === \"object\" ? p.days : {},\n        lessons: p.lessons && typeof p.lessons === \"object\" ? p.lessons : {},\n        settings: { discreet: Boolean(p.settings?.discreet) },\n      };\n    }\n  } catch {\n    // Storage blocked or corrupted — start empty rather than crash\n  }\n  cache = { ...db, ready: true };\n  return cache;\n}\n\nfunction save(next: FeedDB) {\n  cache = { ...next, ready: true };\n  try {\n    localStorage.setItem(KEY, JSON.stringify(next));\n  } catch {\n    // keep working in memory\n  }\n  listeners.forEach((l) => l());\n  changeListeners.forEach((l) => l());\n}\n\nexport function useFeed(): FeedState {\n  return useSyncExternalStore(\n    (cb) => {\n      listeners.add(cb);\n      return () => listeners.delete(cb);\n    },\n    load,\n    () => SERVER_STATE,\n  );\n}\n\nexport const feedStore = {\n  /** Mark an activity Done / Later / Skipped for today. */\n  setChoice(activityId: string, status: ChoiceStatus) {\n    const db = load();\n    const today = dateKey(new Date());\n    save({\n      ...db,\n      days: { ...db.days, [today]: { ...db.days[today], [activityId]: { status, at: new Date().toISOString() } } },\n    });\n  },\n\n  /** Undo today's choice for an activity (back to pending). */\n  clearChoice(activityId: string) {\n    const db = load();\n    const today = dateKey(new Date());\n    const day = { ...db.days[today] };\n    delete day[activityId];\n    save({ ...db, days: { ...db.days, [today]: day } });\n  },\n\n  markLessonRead(lessonId: string) {\n    const db = load();\n    if (db.lessons[lessonId]) return;\n    const now = new Date();\n    save({ ...db, lessons: { ...db.lessons, [lessonId]: { localDate: dateKey(now), at: now.toISOString() } } });\n  },\n\n  setDiscreet(discreet: boolean) {\n    const db = load();\n    save({ ...db, settings: { ...db.settings, discreet } });\n  },\n};\n\n/** Used by account sync: read, replace or clear this phone's copy. */\nexport const feedSync = {\n  get(): FeedDB {\n    // eslint-disable-next-line @typescript-eslint/no-unused-vars\n    const { ready, ...db } = load();\n    return db;\n  },\n  /** Data from his account: saved on the phone and shown, but not sent back again. */\n  replace(db: FeedDB) {\n    try {\n      localStorage.setItem(KEY, JSON.stringify(db));\n    } catch {}\n    cache = null;\n    load();\n    listeners.forEach((l) => l());\n  },\n  clear() {\n    try {\n      localStorage.removeItem(KEY);\n    } catch {}\n    cache = null;\n    listeners.forEach((l) => l());\n  },\n  onChange(cb: () => void) {\n    changeListeners.add(cb);\n    return () => {\n      changeListeners.delete(cb);\n    };\n  },\n};\n",
  "src/lib/progress/store.ts": "\"use client\";\n\n// Saves progress records and goals.\n// NOW: on the phone (localStorage) so it works before sign-up.\n// LATER: this file is swapped for Supabase — the screens don't change.\n\nimport { useSyncExternalStore } from \"react\";\nimport { dateKey } from \"./dates\";\nimport type { Goal, MetricType, RecordMeta, RecordSource, TrackingRecord, Unit } from \"./types\";\n\nconst KEY = \"ms_progress_v1\";\n\ntype DB = { records: TrackingRecord[]; goals: Goal[] };\nexport type ProgressState = DB & { ready: boolean };\n\n// Starting goals — the man can change them.\nconst DEFAULT_GOALS: Goal[] = [\n  { metric: \"water\", target: 2500, unit: \"ml\", period: \"day\", direction: \"increase\", updatedAt: \"\" },\n  { metric: \"sleep\", target: 420, unit: \"min\", period: \"day\", direction: \"increase\", updatedAt: \"\" },\n];\n\n/** Adds any default goal the saved data doesn't have yet (e.g. after a new tracker is added). */\nfunction withDefaults(goals: Goal[]): Goal[] {\n  const missing = DEFAULT_GOALS.filter((d) => !goals.some((g) => g.metric === d.metric));\n  return [...goals, ...missing];\n}\n\nconst SERVER_STATE: ProgressState = { records: [], goals: DEFAULT_GOALS, ready: false };\nlet cache: ProgressState | null = null;\nconst listeners = new Set<() => void>();\n/** Told only about HIS changes (not about data arriving from his account), so they can be saved to it. */\nconst changeListeners = new Set<() => void>();\n\nfunction load(): ProgressState {\n  if (cache) return cache;\n  let db: DB = { records: [], goals: DEFAULT_GOALS };\n  try {\n    const raw = localStorage.getItem(KEY);\n    if (raw) {\n      const parsed = JSON.parse(raw) as Partial<DB>;\n      db = {\n        records: Array.isArray(parsed.records) ? parsed.records : [],\n        goals: withDefaults(Array.isArray(parsed.goals) ? parsed.goals : []),\n      };\n    }\n  } catch {\n    // Storage blocked or corrupted — start empty rather than crash\n  }\n  cache = { ...db, ready: true };\n  return cache;\n}\n\nfunction save(next: DB) {\n  cache = { ...next, ready: true };\n  try {\n    localStorage.setItem(KEY, JSON.stringify(next));\n  } catch {\n    // Storage full or blocked — keep working in memory for this visit\n  }\n  listeners.forEach((l) => l());\n  changeListeners.forEach((l) => l());\n}\n\nfunction newId() {\n  return typeof crypto !== \"undefined\" && \"randomUUID\" in crypto\n    ? crypto.randomUUID()\n    : `${Date.now()}-${Math.random().toString(36).slice(2)}`;\n}\n\n/** React hook: the current records and goals; re-renders when they change. */\nexport function useProgress(): ProgressState {\n  return useSyncExternalStore(\n    (cb) => {\n      listeners.add(cb);\n      return () => listeners.delete(cb);\n    },\n    load,\n    () => SERVER_STATE,\n  );\n}\n\ntype NewRecord = {\n  metric: MetricType;\n  value: number;\n  unit: Unit;\n  source: RecordSource;\n  recordedAt?: Date;\n  note?: string;\n  meta?: RecordMeta;\n};\n\nfunction makeRecord(input: NewRecord): TrackingRecord {\n  const at = input.recordedAt ?? new Date();\n  const now = new Date().toISOString();\n  return {\n    id: newId(),\n    userId: \"local\",\n    metric: input.metric,\n    value: Math.round(input.value * 10) / 10,\n    unit: input.unit,\n    source: input.source,\n    recordedAt: at.toISOString(),\n    localDate: dateKey(at),\n    note: input.note,\n    meta: input.meta,\n    createdAt: now,\n    updatedAt: now,\n  };\n}\n\nexport const progressStore = {\n  addRecord(input: NewRecord): TrackingRecord | null {\n    if (!Number.isFinite(input.value) || input.value <= 0) return null;\n    const record = makeRecord(input);\n    const db = load();\n    save({ records: [...db.records, record], goals: db.goals });\n    return record;\n  },\n\n  updateRecord(id: string, value: number, meta?: RecordMeta) {\n    if (!Number.isFinite(value) || value <= 0) return;\n    const db = load();\n    save({\n      records: db.records.map((r) =>\n        r.id === id\n          ? {\n              ...r,\n              value: Math.round(value * 10) / 10,\n              meta: meta ?? r.meta,\n              source: \"manual\",\n              updatedAt: new Date().toISOString(),\n            }\n          : r,\n      ),\n      goals: db.goals,\n    });\n  },\n\n  deleteRecord(id: string): TrackingRecord | undefined {\n    const db = load();\n    const removed = db.records.find((r) => r.id === id);\n    save({ records: db.records.filter((r) => r.id !== id), goals: db.goals });\n    return removed;\n  },\n\n  /** One value per day (e.g. today's energy rating): replaces today's earlier answer. */\n  setDailyValue(input: NewRecord) {\n    if (!Number.isFinite(input.value) || input.value <= 0) return;\n    const record = makeRecord(input);\n    const db = load();\n    save({\n      records: [\n        ...db.records.filter((r) => !(r.metric === record.metric && r.localDate === record.localDate)),\n        record,\n      ],\n      goals: db.goals,\n    });\n  },\n\n  setGoal(metric: MetricType, target: number, unit: Unit) {\n    if (!Number.isFinite(target) || target <= 0) return;\n    const db = load();\n    const now = new Date().toISOString();\n    const exists = db.goals.some((g) => g.metric === metric);\n    save({\n      records: db.records,\n      goals: exists\n        ? db.goals.map((g) => (g.metric === metric ? { ...g, target: Math.round(target), updatedAt: now } : g))\n        : [...db.goals, { metric, target: Math.round(target), unit, period: \"day\", direction: \"increase\", updatedAt: now }],\n    });\n  },\n};\n\nexport function goalFor(goals: Goal[], metric: MetricType): Goal | undefined {\n  return goals.find((g) => g.metric === metric);\n}\n\n/** Used by account sync: read, replace or clear this phone's copy. */\nexport const progressSync = {\n  get(): DB {\n    // eslint-disable-next-line @typescript-eslint/no-unused-vars\n    const { ready, ...db } = load();\n    return db;\n  },\n  /** Data from his account: saved on the phone and shown, but not sent back again. */\n  replace(db: DB) {\n    try {\n      localStorage.setItem(KEY, JSON.stringify(db));\n    } catch {}\n    cache = null;\n    load();\n    listeners.forEach((l) => l());\n  },\n  clear() {\n    try {\n      localStorage.removeItem(KEY);\n    } catch {}\n    cache = null;\n    listeners.forEach((l) => l());\n  },\n  onChange(cb: () => void) {\n    changeListeners.add(cb);\n    return () => {\n      changeListeners.delete(cb);\n    };\n  },\n};\n",
  "src/lib/social/store.ts": "\"use client\";\n\n// Saves Social data: bookmarks, chosen topics, his posts and replies, reactions and reports.\n// NOW: on this phone only (localStorage). LATER: the server, so other men can see his posts.\n\nimport { useSyncExternalStore } from \"react\";\nimport type { TopicId } from \"../content/types\";\nimport { toggleReaction, type CommunityTopic, type Post, type ReactionKind, type Reply } from \"./community\";\n\nexport interface SocialDB {\n  bookmarks: Record<string, string>; // contentId → saved at\n  interests: TopicId[];\n  nickname: string;\n  posts: Post[]; // his own posts\n  replies: Reply[]; // his own replies\n  reactions: Record<string, ReactionKind[]>; // postId/replyId → his reactions\n  reports: Record<string, { reason: string; at: string }>; // reported items (hidden for him, queued for moderators)\n}\nexport type SocialState = SocialDB & { ready: boolean };\n\nconst KEY = \"ms_social_v1\";\nconst EMPTY: SocialDB = { bookmarks: {}, interests: [], nickname: \"\", posts: [], replies: [], reactions: {}, reports: {} };\nconst SERVER_STATE: SocialState = { ...EMPTY, ready: false };\nlet cache: SocialState | null = null;\nconst listeners = new Set<() => void>();\n/** Told only about HIS changes (not about data arriving from his account), so they can be saved to it. */\nconst changeListeners = new Set<() => void>();\n\nconst obj = <T,>(v: unknown, fallback: T): T => (v && typeof v === \"object\" ? (v as T) : fallback);\n\nfunction load(): SocialState {\n  if (cache) return cache;\n  let db = EMPTY;\n  try {\n    const raw = localStorage.getItem(KEY);\n    if (raw) {\n      const p = JSON.parse(raw) as Partial<SocialDB>;\n      db = {\n        bookmarks: obj(p.bookmarks, {}),\n        interests: Array.isArray(p.interests) ? p.interests : [],\n        nickname: typeof p.nickname === \"string\" ? p.nickname : \"\",\n        posts: Array.isArray(p.posts) ? p.posts : [],\n        replies: Array.isArray(p.replies) ? p.replies : [],\n        reactions: obj(p.reactions, {}),\n        reports: obj(p.reports, {}),\n      };\n    }\n  } catch {\n    // Storage blocked or corrupted — start empty rather than crash\n  }\n  cache = { ...db, ready: true };\n  return cache;\n}\n\nfunction save(next: SocialDB) {\n  cache = { ...next, ready: true };\n  try {\n    localStorage.setItem(KEY, JSON.stringify(next));\n  } catch {\n    // keep working in memory\n  }\n  listeners.forEach((l) => l());\n  changeListeners.forEach((l) => l());\n}\n\nconst id = () =>\n  typeof crypto !== \"undefined\" && \"randomUUID\" in crypto ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`;\n\nexport function useSocial(): SocialState {\n  return useSyncExternalStore(\n    (cb) => {\n      listeners.add(cb);\n      return () => listeners.delete(cb);\n    },\n    load,\n    () => SERVER_STATE,\n  );\n}\n\nexport const socialStore = {\n  toggleBookmark(contentId: string): boolean {\n    const db = load();\n    const next = { ...db.bookmarks };\n    const saved = !next[contentId];\n    if (saved) next[contentId] = new Date().toISOString();\n    else delete next[contentId];\n    save({ ...db, bookmarks: next });\n    return saved;\n  },\n\n  setInterests(interests: TopicId[]) {\n    save({ ...load(), interests });\n  },\n\n  setNickname(nickname: string) {\n    save({ ...load(), nickname: nickname.trim().slice(0, 24) });\n  },\n\n  addPost(input: { topic: CommunityTopic; title: string; body: string; anonymous: boolean; wantsExpert: boolean }): Post {\n    const db = load();\n    const post: Post = {\n      id: id(),\n      topic: input.topic,\n      title: input.title.trim(),\n      body: input.body.trim(),\n      author: input.anonymous || !db.nickname ? { name: \"Anonymous member\", anonymous: true } : { name: db.nickname, anonymous: false },\n      createdAt: new Date().toISOString(),\n      wantsExpert: input.wantsExpert,\n      mine: true,\n    };\n    save({ ...db, posts: [post, ...db.posts] });\n    return post;\n  },\n\n  deletePost(postId: string) {\n    const db = load();\n    save({ ...db, posts: db.posts.filter((p) => p.id !== postId), replies: db.replies.filter((r) => r.postId !== postId) });\n  },\n\n  addReply(postId: string, body: string, anonymous: boolean): Reply {\n    const db = load();\n    const reply: Reply = {\n      id: id(),\n      postId,\n      body: body.trim(),\n      author: anonymous || !db.nickname ? { name: \"Anonymous member\", anonymous: true } : { name: db.nickname, anonymous: false },\n      createdAt: new Date().toISOString(),\n      mine: true,\n    };\n    save({ ...db, replies: [...db.replies, reply] });\n    return reply;\n  },\n\n  deleteReply(replyId: string) {\n    const db = load();\n    save({ ...db, replies: db.replies.filter((r) => r.id !== replyId) });\n  },\n\n  react(targetId: string, kind: ReactionKind) {\n    const db = load();\n    save({ ...db, reactions: { ...db.reactions, [targetId]: toggleReaction(db.reactions[targetId], kind) } });\n  },\n\n  report(targetId: string, reason: string) {\n    const db = load();\n    save({ ...db, reports: { ...db.reports, [targetId]: { reason, at: new Date().toISOString() } } });\n  },\n\n  undoReport(targetId: string) {\n    const db = load();\n    const reports = { ...db.reports };\n    delete reports[targetId];\n    save({ ...db, reports });\n  },\n};\n\n/** Used by account sync: read, replace or clear this phone's copy. */\nexport const socialSync = {\n  get(): SocialDB {\n    // eslint-disable-next-line @typescript-eslint/no-unused-vars\n    const { ready, ...db } = load();\n    return db;\n  },\n  /** Data from his account: saved on the phone and shown, but not sent back again. */\n  replace(db: SocialDB) {\n    try {\n      localStorage.setItem(KEY, JSON.stringify(db));\n    } catch {}\n    cache = null;\n    load();\n    listeners.forEach((l) => l());\n  },\n  clear() {\n    try {\n      localStorage.removeItem(KEY);\n    } catch {}\n    cache = null;\n    listeners.forEach((l) => l());\n  },\n  onChange(cb: () => void) {\n    changeListeners.add(cb);\n    return () => {\n      changeListeners.delete(cb);\n    };\n  },\n};\n"
};

for (const [path, content] of Object.entries(files)) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.log("  wrote", path);
}
console.log("\nDone: " + Object.keys(files).length + " files. Next: npm test, then npx next dev --turbopack, then open http://localhost:3000/me");
